(function (global) {
  'use strict';

  var list = [{"p":"01-大正藏/09經集部類/T0705《佛說布施經》.md","l":98,"id":"T0705","t":"佛說布施經","x":"佛言：「大王！若以十善行施，復得十種報應：十善者，不殺生、不偷盜、不婬欲、不妄語、不綺語、不惡口、不兩舌、不貪、不瞋、不癡，而得命不中夭、財無散失、眷屬清潔、所言誠諦、離諸嫉妬、人所喜見、親友和睦、不墮貧賤、顏貌端正、智慧相應。獲報如是。」"},{"p":"01-大正藏/03般若部類/T0235《金剛般若波羅蜜經》.md","l":18,"id":"T0235","t":"金剛般若波羅蜜經","x":"時，長老須菩提在大眾中即從座起，偏袒右肩，右膝著地，合掌恭敬而白佛言：「希有世尊！如來善護念諸菩薩，善付囑諸菩薩。世尊！善男子、善女人，發阿耨多羅三藐三菩提心，應云何住？云何降伏其心？」"},{"p":"01-大正藏/07涅槃部類/T0378《佛說方等般泥洹經》.md","l":47,"id":"T0378","t":"佛說方等般泥洹經","x":"爾時淨居天子、釋、梵、四天王、魔子導師，各與八十那術之眾，俱到力士所生處叢樹間，前詣佛所，稽首作禮却住一面，同時舉聲為賢者阿難說偈言："},{"p":"01-大正藏/03般若部類/T0240《實相般若波羅蜜經》.md","l":18,"id":"T0240","t":"實相般若波羅蜜經","x":"其名曰：金剛手菩薩、觀自在菩薩、虛空藏菩薩、文殊師利菩薩、轉法輪菩薩、降伏一切魔菩薩。如是等菩薩摩訶薩而為上首。"},{"p":"01-大正藏/05華嚴部類/T0298《大方廣普賢所說經》.md","l":36,"id":"T0298","t":"大方廣普賢所說經","x":"時普賢菩薩，復告大眾：「諸佛子！此法唯是行普賢行，為善知識所攝受者，乃得聞見。是故汝等，於此法門，作金剛心，增上意樂，護持讀誦，勿令忘失。」"},{"p":"01-大正藏/03般若部類/T0233《文殊師利所說般若波羅蜜經》.md","l":20,"id":"T0233","t":"文殊師利所說般若波羅蜜經","x":"爾時世尊一切種智，知諸大眾悉已在門外，從住處起出至門外，自鋪法座結加趺坐。告舍利弗：「汝今晨朝來門外乎？」舍利弗白佛言：「世尊！文殊師利等菩薩摩訶薩，皆悉先至。」"},{"p":"01-大正藏/09經集部類/T0687《佛說孝子經》.md","l":14,"id":"T0687","t":"佛說孝子經","x":"佛問諸沙門：「親之生子，懷之十月，身為重病；臨生之日，母危父怖，其情難言。既生之後，推燥臥濕，精誠之至，血化為乳，摩拭澡浴，衣食教詔，禮賂師友，奉貢君長；子顏和悅，親亦欣豫，子設慘慼，親心焦枯；出門愛念，入則存之，心懷惕惕，懼其不善。親恩若此，何以報之？」"},{"p":"01-大正藏/06寶積部類/T0338《佛說離垢施女經》.md","l":38,"id":"T0338","t":"佛說離垢施女經","x":"無虛見曰：「化其城中一切人民男女大小目所覩者，悉見佛形，至後究竟，逮得無上正真之道。」"},{"p":"01-大正藏/03般若部類/T0237《金剛般若波羅蜜經》.md","l":16,"id":"T0237","t":"金剛般若波羅蜜經","x":"一時佛婆伽婆，住舍衛國祇陀樹林給孤獨園，與大比丘眾千二百五十人俱。爾時世尊，於日前分，著衣持鉢，入舍衛大國而行乞食。於其國中次第行乞，還至本處。飯食事訖，於中後時，收衣鉢，洗足已。如常敷座，加趺安坐，端身而住，正念現前。時諸比丘俱往佛所，至佛所已，頂禮佛足，右遶三匝，却坐一面。"},{"p":"01-大正藏/09經集部類/T0549《佛說光明童子因緣經》.md","l":18,"id":"T0549","t":"佛說光明童子因緣經","x":"時彼長者，遠見世尊漸近自舍，即謂妻言：「我今同汝，詣世尊所。」作是言已，即與其妻，前詣佛所。到已白言：「世尊！我名善賢，此是我妻，其人懷妊，日月將滿，當所生者，是男？是女？」"},{"p":"01-大正藏/10密教部類/T0866《金剛頂瑜伽中略出念誦經》.md","l":33,"id":"T0866","t":"金剛頂瑜伽中略出念誦經","x":"「世尊！復有眾生耽著一切資財、飲食、欲樂，厭惡三摩耶，不勤於供養。是彼人等於壇場隨意作事得入者，一切所求皆得圓滿。"},{"p":"01-大正藏/03般若部類/T0227《小品般若波羅蜜經》.md","l":26,"id":"T0227","t":"小品般若波羅蜜經","x":"一時佛在王舍城耆闍崛山中，與大比丘僧千二百五十人俱，皆是阿羅漢，諸漏已盡，如調象王，所作已辦，捨於重擔，逮得己利，盡諸有結，正智解脫，心得自在，唯除阿難。"},{"p":"01-大正藏/09經集部類/T0664《合部金光明經》.md","l":14,"id":"T0664","t":"合部金光明經","x":"大興善寺沙門釋寶貴者，即近周世道安神足，伏膺明匠、寔曰良才，翫閱群經未嘗釋手，可謂瞿曇身子、孔氏顏淵者焉。"},{"p":"01-大正藏/05華嚴部類/T0303《佛華嚴入如來德智不思議境界經》.md","l":20,"id":"T0303","t":"佛華嚴入如來德智不思議境界經","x":"復共六十百千比丘尼：摩訶鉢囉闍簸帝比丘尼，耶輸陀囉比丘尼為首，皆善集白法，皆近普智智，皆入普智光明行，皆於明法，如是善通諸法無相，如是下入諸法實際，如是順到諸法不生不滅無有助對，如是信解，皆安住不思解脫三摩地，皆隨化度眾生，如無功用無分別色身形類威儀示現。"},{"p":"01-大正藏/03般若部類/T0244《佛說最上根本大樂金剛不空三昧大教王經》.md","l":20,"id":"T0244","t":"佛說最上根本大樂金剛不空三昧大教王經","x":"佛告金剛手菩薩：「若人得聞此一切清淨法門般若波羅蜜多者，是人即得銷除諸障，謂：煩惱障、法障、業障，諸障道法悉皆銷滅，設造地獄之業亦不復受，所有苦惱於剎那頃滅盡無餘，速能至於菩提道場。若人受持讀誦記念思惟，是人現世得一切法平等三摩地，得一切法自在，獲一切愛樂適悅，歷十六大菩薩生而成正覺。」"},{"p":"01-大正藏/17禪宗部類/T2007《南宗頓教最上大乘摩訶般若波羅蜜經六祖惠能大師於韶州大梵寺施法壇經》.md","l":20,"id":"T2007","t":"南宗頓教最上大乘摩訶般若波羅蜜經六祖惠能大師於韶州大梵寺施法壇經","x":"五祖忽於一日喚門人盡來，門人集訖。五祖曰：「吾向汝說，世人生死事大。汝等門人，終日供養，只求福田，不求出離生死苦海。汝等自性迷，福門何可救汝？汝等且歸房自看，有知惠者，自取本性般若知之，各作一偈呈吾。吾看汝偈，若悟大意者，付汝衣法，稟為六代。火急作！」"},{"p":"01-大正藏/09經集部類/T0439《佛說諸佛經》.md","l":26,"id":"T0439","t":"佛說諸佛經","x":"「大目乾連！彼一一佛，從初發心乃至成等正覺，皆是經歷無數之劫。我從發心至今成佛，劫數甚多，不可算計。彼色究竟天，少知少見；汝勿生疑。」"},{"p":"01-大正藏/03般若部類/T0257《佛說聖佛母般若波羅蜜多經》.md","l":16,"id":"T0257","t":"佛說聖佛母般若波羅蜜多經","x":"一時，世尊在王舍城鷲峯山中，與大苾芻眾千二百五十人俱，并諸菩薩摩訶薩眾而共圍繞。"},{"p":"01-大正藏/16淨土宗部類/T1959《觀念阿彌陀佛相海三昧功德法門》.md","l":24,"id":"T1959","t":"觀念阿彌陀佛相海三昧功德法門","x":"觀阿彌陀佛真金色身，圓光徹照端正無比。行者等一切時處晝夜常作此想，行住坐臥亦作此想。每常住意向西，及彼聖眾、一切雜寶莊嚴等相，如對目前。應知。"},{"p":"01-大正藏/07涅槃部類/T1769《涅槃宗要》.md","l":22,"id":"T1769","t":"涅槃宗要","x":"問：彼初師義無因無說，此後師意有因有說。如是二說何得何失？或有說者，二說悉得，皆依經典不相妨故。雖非不然故說有無，無而非定然，故不相違。說經因緣應如是知。"},{"p":"01-大正藏/03般若部類/T0242《佛說遍照般若波羅蜜經》.md","l":16,"id":"T0242","t":"佛說遍照般若波羅蜜經","x":"一時世尊，得一切如來金剛三昧智，得一切如來種種具足最上寶冠，得一切如來大自在相應金剛智，受三界灌頂一切如來智印，乃至圓滿一切眾生所欲之願，種種變化，大明平等智慧，此大毘盧遮那常住三世平等一切如來金剛身語意業，稱讚一切如來。"},{"p":"01-大正藏/04法華部類/T1725《法華宗要》.md","l":30,"id":"T1725","t":"法華宗要","x":"答：〈方便品〉言：「佛以無數方便演說諸法，是法皆為一佛乘故。」此文正是用三為一之證也。又言：「是諸眾生從佛聞法，究竟皆得一切種智。」此言正是將三致一之證也。"},{"p":"01-大正藏/09經集部類/T0572《佛說長者法志妻經》.md","l":18,"id":"T0572","t":"佛說長者法志妻經","x":"佛時清旦，著衣持鉢入城分衛，比丘菩薩皆悉侍從。諸天龍神及香音神，無善之神，鳳凰神，山神、執樂神王，皆散華燒香，鼓諸音樂歌歎佛德，而說頌曰："},{"p":"01-大正藏/07涅槃部類/T0377《大般涅槃經後分》.md","l":16,"id":"T0377","t":"大般涅槃經後分","x":"爾時，須跋陀羅從佛聞說大般涅槃甚深妙法，而得法眼，見法清淨，愛護正法，已捨邪見，於佛法中深信堅固；即從如來，欲求出家。佛言：「善哉，善哉！須跋陀羅！善來比丘，悅可聖心，善入佛道。」於是，須跋陀羅歡喜踊躍，忻慶無量，即時鬚髮自落，而作沙門，法性智水灌注心原，無復縛著，漏盡意解，得羅漢果。"},{"p":"01-大正藏/16淨土宗部類/T1965《遊心安樂道》.md","l":14,"id":"T1965","t":"遊心安樂道","x":"遊心安樂，略開七門：初、述教起宗致；二、定彼土所在；三、明疑惑患難；四、顯往生因緣；五、出往生品數；六、論往生難易；七、作疑復除疑。"},{"p":"01-大正藏/01阿含部類/T0054《釋摩男本四子經》.md","l":18,"id":"T0054","t":"釋摩男本四子經","x":"佛言：「若婬心怒心癡心解者，何因緣復與妻子共居？若有貪心故。其有賢者，自思惟：『雖有經小苦耳，久後大樂，與妻子共居須臾樂耳，久後大苦。』」"},{"p":"01-大正藏/03般若部類/T0223《摩訶般若波羅蜜經》.md","l":22,"id":"T0223","t":"摩訶般若波羅蜜經","x":"爾時世尊舉身毛孔皆亦微笑而放諸光，遍照三千大千國土，復至十方如恒河沙等諸佛國土。若有眾生遇斯光者，必得阿耨多羅三藐三菩提。爾時世尊以常光明遍照三千大千國土，亦至東方如恒河沙等諸佛國土，乃至十方亦復如是。若有眾生遇斯光者，必得阿耨多羅三藐三菩提。"},{"p":"01-大正藏/05華嚴部類/T1868《華嚴一乘十玄門》.md","l":54,"id":"T1868","t":"華嚴一乘十玄門","x":"第七一多相容不同門者，此約理說。以一入多、多入一故名相容，即體無先後，而不失一多之相，故曰不同。此即緣起實德，非天人所修。故經云「以一佛土滿十方，十方入一亦無餘，世界本相亦不壞，自在願力故能爾。」又如〈普賢品〉云「一切眾生身入一眾生身，一眾生身入一切眾生身。」又云「一切諸世界，令入一塵中，世界不積聚，亦復不雜亂。」須彌入芥子，此即不說也。"},{"p":"01-大正藏/01阿含部類/T0031《一切流攝守因經》.md","l":24,"id":"T0031","t":"一切流攝守因經","x":"「何等為，比丘！流從守斷？是聞比丘行者，眼見色，攝眼根自守，行惡露觀；念本從所生。比丘！眼根不守攝，行令從惡露觀，從念本所生流惱熱憂，以眼根守攝止，便從惡露見本觀，便所流惱熱憂便不有，是為，比丘！流從守斷。耳、鼻、口、身、意亦爾。"},{"p":"01-大正藏/03般若部類/T0220《大般若波羅蜜多經》.md","l":22,"id":"T0220","t":"大般若波羅蜜多經","x":"一時，薄伽梵住王舍城鷲峯山頂，與大苾芻眾千二百五十人俱，皆阿羅漢，諸漏已盡無復煩惱，得真自在心善解脫、慧善解脫，如調慧馬亦如大龍，已作所作已辦所辦，棄諸重擔逮得己利，盡諸有結正知解脫，至心自在第一究竟。除阿難陀獨居學地得預流果，大迦葉波而為上首。復有五百苾芻尼眾，皆阿羅漢，大勝生主而為上首。復有無量鄔波索迦、鄔波斯迦，皆見聖諦。"},{"p":"01-大正藏/16淨土宗部類/T0362《佛說阿彌陀三耶三佛薩樓佛檀過度人道經》.md","l":20,"id":"T0362","t":"佛說阿彌陀三耶三佛薩樓佛檀過度人道經","x":"阿難白佛言：「無有諸天神教我，亦無諸佛教我令問佛也。我自從善心知佛意，問佛爾！每佛坐起行來出入，所欲至到、當所作為、諸所教勅者，我輒如佛意。今佛獨當念，諸已過去佛，諸當來佛，若他方佛國，今現在佛，獨展轉相思念故，佛面色光明乃爾耳！」"},{"p":"01-大正藏/05華嚴部類/T0281《佛說菩薩本業經》.md","l":41,"id":"T0281","t":"佛說菩薩本業經","x":"是時，佛放足下相輪光明，悉照佛界諸小國土，一小國土者，一須彌山日月運繞照四天下，東弗于逮，南閻浮提，西拘耶尼，北欝單越，四周大海，鐵垣圍表，上有二十八天，如此者為一小國土，周匝十方合有百億。"},{"p":"01-大正藏/03般若部類/T0239《佛說能斷金剛般若波羅蜜多經》.md","l":16,"id":"T0239","t":"佛說能斷金剛般若波羅蜜多經","x":"一時薄伽梵，在名稱大城，戰勝林施孤獨園，與大苾芻眾千二百五十人俱，及大菩薩眾。爾時，世尊於日初分時，著衣持鉢，入城乞食。次第乞已，還至本處。飯食訖，收衣鉢，洗足已，於先設座，加趺端坐，正念而住。時諸苾芻來詣佛所，頂禮雙足，右繞三匝，退坐一面。"},{"p":"01-大正藏/08大集部類/T0407《虛空藏菩薩神呪經》.md","l":20,"id":"T0407","t":"虛空藏菩薩神呪經","x":"於此眾中有住十地菩薩摩訶薩，得首楞嚴三昧，一生補處最後有身，見如是相不驚怖畏，解諸法空如實際性，是故不驚不怖不畏。餘諸菩薩摩訶薩、聲聞、天、龍、夜叉、乾闥婆、阿修羅、緊那羅、拘槃茶、毘舍遮富單那、迦羅富單那、人及非人，在會中者，極驚怖畏生於憂愁，此彼闇蔽其心動亂，各不相見覩無問處，其事云何？何因緣爾！為是誰力？"},{"p":"01-大正藏/09經集部類/T0676《解深密經》.md","l":22,"id":"T0676","t":"解深密經","x":"與無量大聲聞眾俱，一切調順，皆是佛子，心善解脫，慧善解脫，戒善清淨，趣求法樂；多聞、聞持，其聞積集；善思所思，善說所說，善作所作；捷慧、速慧、利慧、出慧、勝決擇慧、大慧、廣慧、及無等慧，慧寶成就；具足三明，逮得第一現法樂住；大淨福田，威儀寂靜，無不圓滿；大忍柔和，成就無減，已善奉行如來聖教。"},{"p":"01-大正藏/03般若部類/T0221《放光般若經》.md","l":26,"id":"T0221","t":"放光般若經","x":"爾時世尊於師子座復放光明，照於三千大千國土。其中眾生見光明者，盡見東方恒邊沙佛及弟子眾，悉見是間沙訶國土釋迦文佛及諸會眾；十方國土各各相見亦復如是。"},{"p":"01-大正藏/09經集部類/T0467《大乘伽耶山頂經》.md","l":26,"id":"T0467","t":"大乘伽耶山頂經","x":"佛言：「文殊師利！菩提相者獨超三界，雖隨世俗而有名字，遠離一切音聲言說。諸菩薩眾發趣菩提，從初發心則無所趣。是故，文殊師利！諸善男子、善女人，應以遠離發趣之心而住菩提。文殊師利！若諸菩薩能發趣於無所趣者，是則趣向菩提之道。"},{"p":"01-大正藏/01阿含部類/T0034《法海經》.md","l":22,"id":"T0034","t":"法海經","x":"目連白佛：「弟子聞道，如來先化之，為非弟子自悟而成道也。如來聖德，厚重天地，言真而要，弟子誦習，得成道果。如來猶天雨，百穀草木，無不仰榮；弟子德淺道小，人不服信。世尊哀愍聾俗，使一切獲安，得信得正，以濟其志。」目連慇懃苦請至三四五。"},{"p":"01-大正藏/01阿含部類/T0059《諸法本經》.md","l":20,"id":"T0059","t":"諸法本經","x":"「如是，諸比丘！欲為諸法本，更為諸法習，痛為諸法同趣，念為諸法致有，思惟為諸法明道，三昧為諸法第一，智慧為諸法最上，解脫為諸法牢固，泥洹為諸法畢竟。"},{"p":"01-大正藏/09經集部類/T0487《離垢慧菩薩所問禮佛法經》.md","l":28,"id":"T0487","t":"離垢慧菩薩所問禮佛法經","x":"離垢慧菩薩既聞佛許，踊躍無量，而白佛言：「若有善男子、善女人等，於如來所，云何恭敬、禮拜、供養？」"},{"p":"01-大正藏/02本緣部類/T0168《太子墓魄經》.md","l":20,"id":"T0168","t":"太子墓魄經","x":"「王語夫人：『當奈之何？此子將為他國所笑。』夫人語王：『當召相師相之，知當語不？』王即召婆羅門師，使相太子。婆羅門言：『此子非是世間人，為是熒惑耳。外為端正，內懷不祥；危國滅宗，將至不久。不可畜養，宜當生埋，誅而殺之。不除此子，則絕國嗣。』王語夫人：『當如之何？今若不除此子，恐後無復立太子。』於是夫人隨王所為。"},{"p":"01-大正藏/01阿含部類/T0042《鐵城泥犁經》.md","l":24,"id":"T0042","t":"鐵城泥犁經","x":"佛言：「人死入泥犁者，侯王沙門道人乃得與閻羅相見耳，凡餘人者但隨群入。閻羅，地獄王名也。」"},{"p":"01-大正藏/06寶積部類/T0328《佛說須賴經》.md","l":22,"id":"T0328","t":"佛說須賴經","x":"釋便化作數人，蹴罵須賴，言無忌諱。又以石擲捶杖加之於須賴，須賴忍力慈仁不瞋不怨。釋便化作數人，謂須賴言：「仁實見在我，謂為卿殺之何如？」"},{"p":"01-大正藏/10密教部類/T0907《佛頂尊勝心破地獄轉業障出三界祕密陀羅尼》.md","l":22,"id":"T0907","t":"佛頂尊勝心破地獄轉業障出三界祕密陀羅尼","x":"阿微羅𤙖佉(此是中品悉地真言)，大日經悉地品名降伏四魔解脫六趣滿足一切智智金剛字句也，是名入悉地，能生枝葉遍滿四方。光明晃曜入佛法界，名入悉地。若誦一遍，如轉藏經一千遍。"},{"p":"01-大正藏/07涅槃部類/T0391《般泥洹後灌臘經》.md","l":22,"id":"T0391","t":"般泥洹後灌臘經","x":"「七月十五日，自向七世父母、五種親屬、有墮惡道勤苦劇者，因佛作禮福，欲令解脫憂苦，名為灌臘。"},{"p":"01-大正藏/04法華部類/T1718《妙法蓮華經文句》.md","l":16,"id":"T1718","t":"妙法蓮華經文句","x":"有天台大師，法號智顗，昔於如來前親聽茲典，位居五品；聲振兩朝不歷講肆，佛乘懸解。陀羅尼力樂說不窮，常於陳主大極殿，對御講《仁王般若經》，萬乘屈膝，百官彈指。且如觀心釋，妙離有無，取真性作軌，藉資照成徹。敘名詮宗，異於古德，五義覈理，皆扶聖教。自智者弘法三十餘年，獨有《維摩疏》，隋朝奉煬帝勅，撰此之玄文，迺是灌頂法師私記，合二十卷，非智不彈，斯言允矣。"},{"p":"01-大正藏/05華嚴部類/T0278《大方廣佛華嚴經》.md","l":26,"id":"T0278","t":"大方廣佛華嚴經","x":"復有佛世界微塵數諸道場神，其名曰：淨莊嚴神、寶積光明神、吼音聲神、雨眾華神、莊嚴寶光神、善超香神、金色雲神、樂華樹神、莊嚴光神，與如是等道場神俱，皆於先佛造立願行。"},{"p":"01-大正藏/01阿含部類/T0068《賴吒和羅經》.md","l":30,"id":"T0068","t":"賴吒和羅經","x":"賴吒和羅即為佛作禮，而歸到父母前，白言：「我所聞佛經戒不宜居家，居家者不能自淨學佛經道也。意欲除頭髮鬚、被袈裟，作沙門。」"},{"p":"01-大正藏/16淨土宗部類/T1972《淨土或問》.md","l":32,"id":"T1972","t":"淨土或問","x":"問曰：既謂淨穢融通塵塵極樂，何娑婆獨不免於穢耶？答曰：凡夫業感即淨而穢，佛眼所觀即穢如淨，豈釋迦報境而果穢哉？"},{"p":"01-大正藏/06寶積部類/T0334《佛說須摩提菩薩經》.md","l":22,"id":"T0334","t":"佛說須摩提菩薩經","x":"須摩提問佛言：「菩薩云何所生處，人見之常歡喜？云何得大富有常多財寶？云何不為他人之所別離？云何不在母人腹中，常得化生千葉蓮華中立法王前？云何得神足，從不可計億剎土，去到彼間禮諸佛？云何得無讎怨、無侵嫉者？云何所說聞者信從踊躍受行？云何得無殃罪，所作善行無能壞者？云何魔不能得其便？云何臨壽終時佛在前立，為說經法，即令不墮苦痛之處？所問如是。」"},{"p":"01-大正藏/09經集部類/T0586《思益梵天所問經》.md","l":22,"id":"T0586","t":"思益梵天所問經","x":"及四天王釋提桓因等，忉利諸天、夜摩天、兜率陀天、化樂天、他化自在天，及梵王等諸梵天；并餘無量諸天龍、鬼神、夜叉、犍闥婆、阿修羅、迦樓羅、緊那羅、摩睺羅伽，人與非人普皆來集。"},{"p":"01-大正藏/09經集部類/T0499《佛為阿支羅迦葉自化作苦經》.md","l":20,"id":"T0499","t":"佛為阿支羅迦葉自化作苦經","x":"時有阿支羅迦葉，為營小事，出王舍城，向耆闍崛山。遙見世尊，見已詣佛所，白佛言：「瞿曇！欲有所問，寧有閑暇見答與不？」"},{"p":"01-大正藏/05華嚴部類/T0292《度世品經》.md","l":26,"id":"T0292","t":"度世品經","x":"普智菩薩覩諸菩薩皆來雲集亦復踊躍，前問普賢菩薩大士：「善哉，佛子！今諸菩薩十方來會，渴仰經典，瞻戴仁者如冥思明。唯為解說諸菩薩行，從始至終令無疑——結者亘然，如病得愈、盲者得目。"},{"p":"01-大正藏/03般若部類/T2732《梁朝傅大士頌金剛經》.md","l":14,"id":"T2732","t":"梁朝傅大士頌金剛經","x":"若有人持誦金剛般若波羅蜜經。先須至心念淨口業真言。然後啟請八金剛四菩薩名號。所在之處常當擁護。"},{"p":"01-大正藏/07涅槃部類/T0383《摩訶摩耶經》.md","l":20,"id":"T0383","t":"摩訶摩耶經","x":"當於爾時，日、月、星辰所有威光隱蔽不現，皆悉來入如來光中，令波利質多羅樹如真金色。譬如虛空淨無雲翳，日月威光極為明顯；如來在於忉利天上所放光明亦復如是，倍更照耀不可譬類。是時，日、月、星辰諸天子等見此相已，其心戰怖不能自安，不知何緣而有斯事。"},{"p":"01-大正藏/09經集部類/T0560《佛說老母女六英經》.md","l":16,"id":"T0560","t":"佛說老母女六英經","x":"有一母人，貧老傴僂，長跪問佛：「五陰、六衰會合我身，悉為是誰？來何所從？去何所歸？惟願世尊為我思惟！」"},{"p":"01-大正藏/02本緣部類/T0171《太子須大拏經》.md","l":28,"id":"T0171","t":"太子須大拏經","x":"「時有敵國怨家，聞太子好喜布施，在所求索不逆人意。即會諸臣及眾道士共集議言：『葉波國王有行蓮華上白象，名須檀延，多力健鬪。每與諸國共相攻伐，此象常勝。誰能往乞者？』諸臣咸言：『無能往得者。』中有道士八人，即白王言：『我能往乞之。當給我資粮。』王即給之。王便語言：『能得象者，我重賞汝。』"},{"p":"01-大正藏/17禪宗部類/T1995《法演禪師語錄》.md","l":22,"id":"T1995","t":"法演禪師語錄","x":"入院日。上堂。僧問。携笻領眾祖令當行。把斷封疆師意如何。師云。秋風吹渭水。落葉滿長安。學云。四面無門山岳秀。今朝且得主人歸。師云。儞道路頭在什麼處。學云。為什麼對面不相識。師云。且喜到來。乃舉。祖師道。吾本來茲土。傳法救迷情。一花開五葉。結果自然成。達磨大師信脚來信口道。後代兒孫多成計校。要會開花結果處麼。鄭州梨青州棗。萬物無過出處好。"},{"p":"01-大正藏/17禪宗部類/T1991《金陵清涼院文益禪師語錄》.md","l":22,"id":"T1991","t":"金陵清涼院文益禪師語錄","x":"江南國主。重師之道。迎住報恩禪院。署淨慧禪師。僧問。鐘洪纔擊。大眾雲臻。請師如是師云。大眾會。何似汝會。"},{"p":"01-大正藏/09經集部類/T0749《佛說因緣僧護經》.md","l":22,"id":"T0749","t":"佛說因緣僧護經","x":"龍聞大聲，即便覺寤，還為比丘，加趺坐禪。因聲高大，大眾運集，問此年少比丘：「何故揚聲？」比丘答曰：「房中有龍。」"},{"p":"01-大正藏/09經集部類/T0741《五苦章句經》.md","l":18,"id":"T0741","t":"五苦章句經","x":"「二曰人道苦。有百千種，人實為疲勞。從奴婢、下使、乞兒、賤人，中間富貴，上至帝王、轉輪聖王，皆有生老病死、飢渴寒熱、苦痛愁惱、憂患災變，或有兵賊、牢獄刑戮、火燒水溺、墜落堆廅、塼石刀杖、奔車逸馬、怨家劫盜，更相傷害：其死萬端，一切眾生，未脫三界，皆共有之，是謂二苦。"},{"p":"01-大正藏/05華嚴部類/T0286《十住經》.md","l":26,"id":"T0286","t":"十住經","x":"「又，金剛藏！汝當說此法門差別，所謂諸佛神力故、汝能堪受如來神力故、自善根清淨故、清淨法性性故、饒益眾生性故、令眾生得清淨法身智身故、於一切佛得受記故、得一切世間最高大身故、過一切世間道故、出世間善根清淨故。」"},{"p":"01-大正藏/06寶積部類/T0353《勝鬘師子吼一乘大方便方廣經》.md","l":65,"id":"T0353","t":"勝鬘師子吼一乘大方便方廣經","x":"「世尊！我從今日乃至菩提，不自為己行四攝法，為一切眾生故，以不愛染心、無厭足心、無罣礙心，攝受眾生。"},{"p":"01-大正藏/09經集部類/T0601《佛為娑伽羅龍王所說大乘經》.md","l":20,"id":"T0601","t":"佛為娑伽羅龍王所說大乘經","x":"「龍主！汝當觀此大海之眾，見作種種士夫色相。龍主！而彼一切色相，由於一切善惡身、口、意業，各各之心，種種變化；然此心法，雖云色相，由如幻化，無可取故。"},{"p":"01-大正藏/02本緣部類/T0177《大意經》.md","l":20,"id":"T0177","t":"大意經","x":"「父母念言：『子初生時，已有是願。』便告子言：『吾財無數，自恣意所施與，不相禁制也。』大意報言：『父母財物雖多，猶不足我用，唯當入海採七寶，以給施天下人民耳。』數言如是，父母即聽使行。"},{"p":"01-大正藏/18史傳部類/T2034《歷代三寶紀》.md","l":1220,"id":"T2034","t":"歷代三寶紀","x":"右一十一部合一十二卷。西域沙門支曜。靈帝世中平年。於雒陽譯其七部。是吳錄所載。"},{"p":"01-大正藏/16淨土宗部類/T0366《佛說阿彌陀經》.md","l":22,"id":"T0366","t":"佛說阿彌陀經","x":"「又舍利弗！極樂國土有七寶池，八功德水充滿其中，池底純以金沙布地。四邊階道，金、銀、琉璃、頗梨合成；上有樓閣，亦以金、銀、琉璃、頗梨、車𤦲、赤珠、馬瑙而嚴飾之。池中蓮花，大如車輪，青色青光，黃色黃光，赤色赤光，白色白光，微妙香潔。舍利弗！極樂國土成就如是功德莊嚴。"},{"p":"01-大正藏/03般若部類/T0255《般若波羅蜜多心經》.md","l":18,"id":"T0255","t":"般若波羅蜜多心經","x":"時，具壽舍利子，承佛威力，白聖者觀自在菩薩摩訶薩曰：「若善男子欲修行甚深般若波羅蜜多者，復當云何修學？」作是語已。"},{"p":"01-大正藏/04法華部類/T1723《妙法蓮華經玄贊》.md","l":18,"id":"T1723","t":"妙法蓮華經玄贊","x":"經「如是我聞」。贊曰：初釋經文略以六門料簡：一敘經起之意，二明經之宗旨，三解經品得名，四顯經品廢立，五彰品之次第，六釋經之本文。"},{"p":"01-大正藏/03般若部類/T0260《佛說開覺自性般若波羅蜜多經》.md","l":18,"id":"T0260","t":"佛說開覺自性般若波羅蜜多經","x":"「復次，須菩提！色於如是三性中轉，愚是所行，當知是為菩薩正行。如是行者，是菩薩速疾證得阿耨多羅三藐三菩提果。"},{"p":"01-大正藏/01阿含部類/T0070《數經》.md","l":22,"id":"T0070","t":"數經","x":"「汝數，目犍連！若作是說，為等說不？次第教授、次第學，行戒教學。此目犍連！若作是說，為次第說不？於我法律，何以故，此目犍連！於我法律次第有教授、次第行戒次第學？此目犍連！謂彼為比丘初學不久，至此法律亦未從如來教語之。此比丘！身行等淨其行，口意等淨其行。此目犍連！若比丘，身行等淨其行，口意等淨其行，彼如來無上御之。"},{"p":"01-大正藏/01阿含部類/T0071《梵志頞波羅延問種尊經》.md","l":20,"id":"T0071","t":"梵志頞波羅延問種尊經","x":"頞波羅延言：「佛持正道，能答應正道者，欲持婆羅門種往，不其有持道道正也。」五百人皆言：「我曹持頞波羅延作師，何為不往講是四種事？」如是者再三，頞波羅延即起，與五百人俱到佛所祇樹。"},{"p":"01-大正藏/10密教部類/T1111《青頸觀自在菩薩心陀羅尼經》.md","l":18,"id":"T1111","t":"青頸觀自在菩薩心陀羅尼經","x":"「(相傳言，每入道場時，先䠒跪懺悔發願已，結跏趺坐，即結淨三業印及習真言，次結三部護身印已，即結後根本印，誦真言七遍，頂上散印。然捧珠，或百或千，依時持)。」"},{"p":"01-大正藏/02本緣部類/T0173《福力太子因緣經》.md","l":29,"id":"T0173","t":"福力太子因緣經","x":"「又復一時，彼廣照后，忽起思念，乃作是言：『我今往彼大金寶聚，踞於其上，隨意舉手，自取金寶，普為一切，廣行布施，使匱乏者財寶豐盈。』以事聞王，王隨所作。"},{"p":"01-大正藏/08大集部類/T0409《觀虛空藏菩薩經》.md","l":28,"id":"T0409","t":"觀虛空藏菩薩經","x":"說是語時，時虛空藏菩薩，結加趺坐，放金色光，如意珠中見三十五佛已，白佛言：「世尊！我此如意珠寶從首楞嚴出，是故眾生見珠者，得如意自在。」"},{"p":"01-大正藏/08大集部類/T0420《自在王菩薩經》.md","l":22,"id":"T0420","t":"自在王菩薩經","x":"自在王菩薩得蒙聽許喜悅無量，白佛言：「世尊！云何菩薩摩訶薩，於大乘法中得自在行，而能為人演說此法，以自在力，摧伏諸魔增上慢者，及諸外道有所見得諸貪著者，令住大乘具足大願成就戒行，得阿耨多羅三藐三菩提？」"},{"p":"01-大正藏/05華嚴部類/T1732《大方廣佛華嚴經搜玄分齊通智方軌》.md","l":14,"id":"T1732","t":"大方廣佛華嚴經搜玄分齊通智方軌","x":"此經本外國凡有十萬偈，昔晉道人支法領，從于闐國得此三萬六千偈，以晉義熙十四年歲次鶉火三月十日，於楊州謝司空寺，天竺禪師佛度跋陀羅手執梵文，譯胡音為晉，沙門釋法業親從筆授，時吳郡內史孟顗、右衛將軍褚叔度為檀越。至元熙二年六月十日出訖胡本，至太宋永初二年辛酉之歲十二月二十八日校畢。"},{"p":"01-大正藏/17禪宗部類/T2006《人天眼目》.md","l":26,"id":"T2006","t":"人天眼目","x":"僧問。如何是奪人不奪境。師云。煦日發生鋪地錦。嬰兒垂髮白如絲(大慧云。此二句。一句存境。一句奪人)。"},{"p":"01-大正藏/09經集部類/T0460《佛說文殊師利淨律經》.md","l":20,"id":"T0460","t":"佛說文殊師利淨律經","x":"時有天子，名曰寂順律音，在於會坐，即從坐起，更整衣服，長跪叉手，白世尊曰：「文殊師利今為所在？一切諸會四部之眾，天、龍、鬼神，釋梵四王，皆共渴仰，欲覩正士咨講妙辭聽受經義。」"},{"p":"01-大正藏/01阿含部類/T0077《尊上經》.md","l":45,"id":"T0077","t":"尊上經","x":"「今是世尊時！今是善逝時！願世尊，當為諸比丘，說此賢善偈及以義。從世尊聞已，比丘當奉持之。」"},{"p":"01-大正藏/05華嚴部類/T0293《大方廣佛華嚴經》.md","l":20,"id":"T0293","t":"大方廣佛華嚴經","x":"復與五百聲聞眾俱，其諸聲聞有大威德，悉覺真諦，皆證實際，深入法性，永出有海，依於如來虛空境界，離結使縛不著依處，其心寂靜猶如虛空，於諸佛所永斷疑惑，於佛智海深信趣入。"},{"p":"01-大正藏/02本緣部類/T0155《菩薩本行經》.md","l":24,"id":"T0155","t":"菩薩本行經","x":"「作是願已，應時三千大千世界為大震動，諸天宮殿𡶅峨踊沒。時，諸天人馳動惶懅。釋提桓因即以天眼觀閻浮提，見於菩薩在於塚間以身布施，即便來下而欲試之，化作眾狗飛鳥走獸，欲來食之。於是菩薩而見眾狗諸飛鳥輩來噉其身，心便歡喜無有退轉傾動之意。於時，天帝還復釋身而讚歎言：『善哉善哉！甚奇難及！所作功德欲求何願？天帝、梵王、轉輪王乎？』"},{"p":"01-大正藏/16淨土宗部類/T1748《無量壽經連義述文贊》.md","l":26,"id":"T1748","t":"無量壽經連義述文贊","x":"經曰「萬二千人俱」者，述云：此第二、唱數也。彼論亦云「數成就者，謂大眾無數故，總別雖異其義一焉。」而帛延唱千二百五十人者，略舉常眾不盡之言，故亦不違。"},{"p":"01-大正藏/09經集部類/T0790《佛說孛經抄》.md","l":22,"id":"T0790","t":"佛說孛經抄","x":"女如其言，往來一月。師使四人，共殺埋之。分布求已，詣闕告言：「生亡一女，眾人悉見日日往來諸沙門所，乞吏搜求。」王即勅外部吏與行。諸師乃佯徘徊再三過，出尸輿載，遍行啼哭曰：「沙門之法，戒當清淨，反婬人婦。恐事發覺，殺而藏之，有何道哉！」國人聞此，多有信者，惟得道之人知諂偽耳。"},{"p":"01-大正藏/09經集部類/T0521《佛說梵摩難國王經》.md","l":20,"id":"T0521","t":"佛說梵摩難國王經","x":"王有太子，名均鄰儒，至心精進，覺世非常，無生不死者，不貪時榮，白王言：「佛世難值，經法難聞，我今乞欲隨佛作沙門。」王即聽之。"},{"p":"01-大正藏/09經集部類/T0509《阿闍世王授決經》.md","l":20,"id":"T0509","t":"阿闍世王授決經","x":"時有貧窮老母，常有至心欲供養佛而無資財，見王作此功德乃更感激，行乞得兩錢，以至麻油家買膏。膏主曰：「母人大貧窮，乞得兩錢，何不買食以自連繼，用此膏為？」"},{"p":"01-大正藏/02本緣部類/T0176《師子月佛本生經》.md","l":20,"id":"T0176","t":"師子月佛本生經","x":"有一梵志，上啟大王頻婆娑羅，白言大王：「沙門釋子作諸非法，乃與鳥獸作那羅戲。」王聞此語，嫌諸釋子，即敕長者迦蘭陀曰：「此諸釋子多聚獼猴，在卿園中為作何等？如來知不？」長者啟王：「婆須蜜多作變化事，令諸獼猴一切歡喜，諸天雨花持用供養。為作何等？臣所不知。」"},{"p":"01-大正藏/05華嚴部類/T0309《最勝問菩薩十住除垢斷結經》.md","l":26,"id":"T0309","t":"最勝問菩薩十住除垢斷結經","x":"佛言執志：「若有族姓子、族姓女，心志質直等住定意可遊彼土，設百千劫於吾之土建立梵行，不如忍界彈指之間無高下意，是為殊勝億千萬倍。」"},{"p":"01-大正藏/04法華部類/T0271《佛說菩薩行方便境界神通變化經》.md","l":18,"id":"T0271","t":"佛說菩薩行方便境界神通變化經","x":"摩訶波闍波提，耶輸陀羅等，與八億比丘尼俱，一切成就白淨之法，皆悉善行，一切智道近一切智，善行進入無有法性，觀一切法無有性相，自解諸法實際無際，得於無礙解脫智慧，隨應眾生，所應調伏，善能示現。"},{"p":"01-大正藏/06寶積部類/T0350《佛說遺日摩尼寶經》.md","l":20,"id":"T0350","t":"佛說遺日摩尼寶經","x":"「菩薩有四事，世世亡菩薩道意。何等為四？一者欺調其師；二者主持他人長短，人無長短誹謗之；三者壞敗菩薩道；四者罵詈為菩薩道者；是為四。"},{"p":"01-大正藏/09經集部類/T0504《比丘聽施經》.md","l":20,"id":"T0504","t":"比丘聽施經","x":"座中有一比丘，即行白佛：「有一比丘，字聽施，來到講堂，謂諸比丘言：『今我不可經法，大著睡眠，不樂道行，疑諸經法。』」"},{"p":"01-大正藏/02本緣部類/T0156《大方便佛報恩經》.md","l":24,"id":"T0156","t":"大方便佛報恩經","x":"阿難聞是語已，心生慙愧。乞食已，還詣佛所，頭面禮足，却住一面，合掌白佛言：「世尊！佛法之中。頗有孝養父母不耶？」"},{"p":"01-大正藏/08大集部類/T0411《大乘大集地藏十輪經》.md","l":22,"id":"T0411","t":"大乘大集地藏十輪經","x":"又因光明，見諸佛土一切有情所受眾苦，無不休息，皆悉歡娛受諸妙樂。又見如是諸佛土中，由此光明之所照觸，遠離一切昏雲、塵霧、烈風、暴雨、不善音聲，及諸臭穢、苦辛、惡味、惡觸、恐怖；遠離一切邪業、邪語、邪意、邪歸；不寒不熱，安靜坦然，地平如掌，諸妙樂具充滿其中。"},{"p":"01-大正藏/01阿含部類/T0016《尸迦羅越六方禮經》.md","l":22,"id":"T0016","t":"尸迦羅越六方禮經","x":"佛言：「聽之，內著心中。其有長者𭶑人能持四戒不犯者，今世為人所敬，後世生天上。一者不殺諸群生、二者不盜、三者不愛他人婦女、四者不妄言兩舌。心欲貪婬、恚怒、愚癡，自制勿聽。不能制此四意者，惡名日聞，如月盡時光明稍冥。能自制惡意者，如月初生其光稍明，至十五日盛滿時也。」"},{"p":"01-大正藏/01阿含部類/T0021《梵網六十二見經》.md","l":20,"id":"T0021","t":"梵網六十二見經","x":"諸比丘白佛言：「向者會共議言：『異道人須卑，及弟子梵達摩納，常隨佛及比丘僧受請。異道人須卑，謗佛及法、比丘僧無央數；弟子梵達摩納，嗟歎佛及法、比丘僧無央數。』」"},{"p":"01-大正藏/17禪宗部類/T2008《六祖大師法寶壇經》.md","l":48,"id":"T2008","t":"六祖大師法寶壇經","x":"時，大師至寶林。韶州韋刺史(名璩)與官僚入山請師，出於城中大梵寺講堂，為眾開緣說法。師陞座次，刺史官僚三十餘人，儒宗學士三十餘人，僧尼道俗一千餘人，同時作禮，願聞法要。"},{"p":"01-大正藏/09經集部類/T0569《佛說心明經》.md","l":33,"id":"T0569","t":"佛說心明經","x":"於是，世尊尋即顯露廣長之舌，以覆其面上至梵天，告梵志曰：「吾從無數億百千劫，常行至誠六度無極，施諸所安，有而不惜，乃獲斯舌，寧以妄語能致之乎？吾欲問，卿至誠答之。曾頗往返舍衛羅閱，中路有樹名尼拘類，蔭庇人眾五百乘車乎？」"},{"p":"01-大正藏/07涅槃部類/T0375《大般涅槃經》.md","l":26,"id":"T0375","t":"大般涅槃經","x":"時諸眾生共相謂言：「且各裁抑，莫大愁苦。當共疾往詣拘尸城力士生處，至如來所頭面禮敬，勸請如來莫般涅槃，住世一劫、若減一劫。」互相執手，復作是言：「世間虛空，眾生福盡，不善諸業增長出世。仁等今當速往速往，如來不久必入涅槃。」復作是言：「世間虛空，世間虛空。我等從今無有救護、無所宗仰，貧窮孤露。一旦遠離無上世尊，設有疑惑，當復問誰？」"},{"p":"01-大正藏/18史傳部類/T2051《唐護法沙門法琳別傳》.md","l":39,"id":"T2051","t":"唐護法沙門法琳別傳","x":"高祖又問諸群臣曰。傅弈每言於朕云。佛教無用。朕欲從其所議。卿等如何。時左僕射魏國公裴寂。進諫於。"},{"p":"01-大正藏/10密教部類/T1037《觀自在菩薩說普賢陀羅尼經》.md","l":30,"id":"T1037","t":"觀自在菩薩說普賢陀羅尼經","x":"「曩謨囉怛曩(二合)怛囉(二合引)野耶曩莫阿(引)哩野(二合引)嚩盧枳帝濕嚩(二合)囉(引)野冐地薩怛嚩(二合)野摩訶薩怛嚩(二合)野摩訶迦嚕抳迦(引)野怛儞也(二合)他止里滿馱(引)銘(上)弭里滿馱(引)弭止里弭里滿馱(引)弭枲(引)摩滿馱(引)弭枲(引)摩(引)銘羯室旨(二合)娜底訖囉(二合)麼覩娑嚩(二合引)訶(引)」"},{"p":"01-大正藏/08大集部類/T0422《大集譬喻王經》.md","l":28,"id":"T0422","t":"大集譬喻王經","x":"「奢利弗！譬如國王第一夫人產生八子，於諸子中惟有一子具足王相，得紹王位以水灌頂，餘諸王子復悉圍遶依法奉事。奢利弗！於意云何，非彼母腹而有過失，令餘王子不得灌頂大王位耶？」"},{"p":"01-大正藏/05華嚴部類/T0299《大方廣總持寶光明經》.md","l":22,"id":"T0299","t":"大方廣總持寶光明經","x":"佛言：「善男子！此法界無性，無能知者。何以故？善男子！由如虛空，離諸戲論、非離戲論，非取、非捨，非性、非無性，亦無處所。善男子！是故法界應如是知。」"},{"p":"01-大正藏/06寶積部類/T0324《佛說幻士仁賢經》.md","l":20,"id":"T0324","t":"佛說幻士仁賢經","x":"是時，王舍大城中，有一幻士名曰颰陀(晉言仁賢)，明經解術曉了幻伎，所作巧黠多所喜悅，所興如意名聞于遠，其摩竭國諸餘幻者皆所不及，所至到處最上第一。除諸見諦清淨士女得法忍者，一切人民莫不傾側。如所言者無不迷惑，隨未曾有法，而以此幻邪行之術，得眾利養。"},{"p":"01-大正藏/09經集部類/T0551《佛說摩鄧女經》.md","l":22,"id":"T0551","t":"佛說摩鄧女經","x":"母語阿難：「我女欲為卿作妻。」阿難言：「我持戒，不畜妻。」復言：「我女不得卿為夫者，便自殺。」阿難言：「我師佛，不得與女人共交通。」"},{"p":"01-大正藏/03般若部類/T2746《般若波羅蜜多心經還源述》.md","l":34,"id":"T2746","t":"般若波羅蜜多心經還源述","x":"此外護也。文自兩重。一控引。二說呪。其文易了。無勞重釋。按呪者持也。持有四種。一法。二義。三辭。四理。內護理總持也。外護辭總持也。但此辭。同體大覺。乃能窮盡。十位菩薩。皆所未通。得本行本。不可翻譯。雖然大意有三。一詮甚深般若。二名大力天神。三片浮遊鬼魅。諸佛慈善。密意在中。所以誦持。必招靈祐。此為外護也。頌言。"},{"p":"01-大正藏/03般若部類/T0229《佛說佛母寶德藏般若波羅蜜經》.md","l":88,"id":"T0229","t":"佛說佛母寶德藏般若波羅蜜經","x":"「佛子當住四補特伽羅，是行大智行：一真實善法；二不退心；三應供離垢無煩惱無求；四善友同等。"},{"p":"01-大正藏/04法華部類/T0263《正法華經》.md","l":24,"id":"T0263","t":"正法華經","x":"於是彌勒菩薩心自念言：「今者世尊，如來、至真、等正覺，三昧正受，現大感變，多所降伏，覩未曾有，天上世間諸佛廟寺，恢闊彰顯，將何所興而有此瑞？從昔暨今未曾見也。欲問其歸，孰堪發遣解斯誼乎？」尋改思曰：「今者大士溥首童真，所作已辦靡所不達，供養過去無數諸佛，曾當瞻覲如來、至真、等正覺，如此瑞應欲請問之。」"},{"p":"01-大正藏/04法華部類/T1719《法華文句記》.md","l":16,"id":"T1719","t":"法華文句記","x":"言「文句」者，文謂文字，一部始終，故云文即是字，為二所依；句謂句讀，義通長短，故云名詮自性、句詮差別。此亦不論色行等體，今但以句而分其文，故云文句。古之章疏，或單題疏，或單題章。章謂章藻，《詩》云：「彼都人士出言成章」；亦云章段，分段解釋成若干章。疏者，通意之辭，亦記也。又疎音即疏通、疏條、疎鏤也。今並不云者，意如向說。"},{"p":"01-大正藏/02本緣部類/T0170《德光太子經》.md","l":20,"id":"T0170","t":"德光太子經","x":"於是，賢者賴吒和羅行到佛所，稽首佛足，却住一面。賴吒和羅問世尊言：「菩薩大士奉行何等，得一切奇特功德之法，致無動畏之慧、超異之智；發遣辯才，光明徹照，入一切智，教授眾生；令得解脫斷於狐疑，以善權方便示一切智；言行相應，所問諸佛，常以巧便得諸佛意；一切所聞法，皆能受持疾逮一切智？」"},{"p":"01-大正藏/03般若部類/T1710《般若波羅蜜多心經幽贊》.md","l":19,"id":"T1710","t":"般若波羅蜜多心經幽贊","x":"餘經復說，佛以一音演無邊義，眾生隨類各得解等，既猶天鼓應念發聲，亦類末尼如求雨寶，應物雖設種種法門，智見純和，未生乖競。佛涅槃後，因彼大天人、法糺紛，初封著有，如有頌曰："},{"p":"01-大正藏/01阿含部類/T0076《梵摩渝經》.md","l":30,"id":"T0076","t":"梵摩渝經","x":"梵摩渝從弟子聞天師之德，愕然流淚曰：「吾年西垂，殆至徒生徒死，不覩天師之上明矣。」摩渝喜曰：「吾以遇哉！覩佛而死，厥榮難云。愚夫雖有天地之壽，何異乎土石之類哉？」即興正服五體投地，三頓首曰：「歸佛、歸法、歸命聖眾。願吾殘命有餘，得在覲見稽首稟化。」"},{"p":"01-大正藏/02本緣部類/T0154《生經》.md","l":20,"id":"T0154","t":"生經","x":"諸比丘聞，便往啟佛。世尊應時，遣人呼比丘來。輙即受教。比丘至，皆為佛作禮，却坐一面。佛即為比丘，蠲色欲念，除癡愛失，為說：「塵勞之穢，樂少憂多，多壞少成，無有節限。唯有佛及諸弟子明智之人，分別是耳。愛慾罪生，不可稱限，超越色慾，休息眾想，閑居講諦。」時族姓子，尋時證明賢聖之法。"},{"p":"01-大正藏/06寶積部類/T0332《佛說優填王經》.md","l":23,"id":"T0332","t":"佛說優填王經","x":"逝心曰：「非爾女人所知，汝不樂者便還歸。」乃自將女詣佛所，稽首佛足，白佛言：「大人勤勞教授，身無供養。有是麁女，願給箕箒。」"},{"p":"01-大正藏/04法華部類/T0262《妙法蓮華經》.md","l":24,"id":"T0262","t":"妙法蓮華經","x":"妙法蓮華經者，統諸佛降靈之本致也。蘊結大夏，出彼千齡。東傳震旦，三百餘載。西晉惠帝永康年中，長安青門燉煌菩薩竺法護者，初翻此經，名正法華。東晉安帝隆安年中，後秦弘始，龜茲沙門鳩摩羅什次翻此經，名妙法蓮華。隋氏仁壽，大興善寺北天竺沙門闍那笈多後所翻者，同名妙法。三經重沓，文旨互陳。時所宗尚，皆弘秦本。自餘支品、別偈，不無其流，具如序曆，故所非述。"},{"p":"01-大正藏/09經集部類/T0781《佛說佛十力經》.md","l":20,"id":"T0781","t":"佛說佛十力經","x":"「復次，如來於過去、未來、現在一切有情諸所作業，若事若處、若因若報，皆如實知。由實知故，是為如來第二業智力。如來、應供、正等正覺具是力者，即能了知廣大勝處，於大眾中作師子吼，轉妙梵輪。"},{"p":"01-大正藏/03般若部類/T0249《佛說帝釋般若波羅蜜多心經》.md","l":55,"id":"T0249","t":"佛說帝釋般若波羅蜜多心經","x":"「曩謨鉢囉(二合)倪也(二合)波(引)囉彌多(引)曳怛儞也(二合)他(引)誐帝誐帝波(引)囕誐帝波(引)囉僧誐帝冒地娑嚩(二合、引)賀」"},{"p":"01-大正藏/10密教部類/T0928《修藥師儀軌布壇法》.md","l":110,"id":"T0928","t":"修藥師儀軌布壇法","x":"我所說者，于常行者同，又見《雜阿含經》及《涅槃》等經所說佛現神變日(二月二日)、得證菩提日、初轉法輪日，及下還日。此四大吉日，凡作善事者，勝常日千百億倍，功德無量矣(二修習法載于本經)。"},{"p":"01-大正藏/09經集部類/T0432《佛說十吉祥經》.md","l":20,"id":"T0432","t":"佛說十吉祥經","x":"時大會中有一大士，名離垢蓋，承佛威神，即從座起，偏袒右肩，右膝著地，叉手合掌，前白佛言：「今可現有諸佛世尊如來、至真、等正覺，若有善男子、善女人求佛道者，聞其名號受持讀誦，疾得不退轉於無上正真道？」"},{"p":"01-大正藏/17禪宗部類/T1997《圓悟佛果禪師語錄》.md","l":68,"id":"T1997","t":"圓悟佛果禪師語錄","x":"住成都府崇寧萬壽禪寺。師在昭覺。初受六祖請。拈帖示眾云。幸自無事。須要箇護身符子作麼。然禍不入慎家之門。且作麼生斷這公案。會麼。兵隨印轉。請維那剖露。"},{"p":"01-大正藏/16淨土宗部類/T1957《略論安樂淨土義》.md","l":16,"id":"T1957","t":"略論安樂淨土義","x":"答曰：「如釋論言：『如斯淨土，非三界所攝。』何以故？無欲故，非欲界；地居故，非色界；有形色故，非無色界。經曰：『阿彌陀佛本行菩薩道時，作比丘，名曰法藏。於世自在王佛所，請問諸佛淨土之行，時佛為說二百一十億諸佛剎土，天人善惡，國土精麁，悉現與之。于時法藏菩薩，即於佛前，發弘誓大願，取諸佛土。』於無量阿僧祇劫，如所發願，行諸波羅蜜，萬善圓滿，成無上道。別業所得，非三界也。」"},{"p":"01-大正藏/06寶積部類/T0343《佛說太子刷護經》.md","l":14,"id":"T0343","t":"佛說太子刷護經","x":"佛在羅閱祇耆闍崛山中時，與千二百比丘，菩薩萬二千人，優婆塞、優婆夷，諸天王梵釋，及無央數人民、鬼神、龍皆來俱會。阿闍世王太子，名為刷護，從國中與群臣長者子五百人，各持黃金華蓋，出羅閱國相隨出至佛所，持黃金華蓋上佛已，却叉手持，頭面著地為佛作禮訖竟，皆叉手住。"},{"p":"01-大正藏/01阿含部類/T0055《苦陰因事經》.md","l":20,"id":"T0055","t":"苦陰因事經","x":"於是釋大力士從座起，一面著衣，叉手向世尊，白世尊曰：「如是我今於世尊有信樂唯願世尊！善為說法謂見法令疑盡。」"},{"p":"01-大正藏/10密教部類/T0946《大佛頂廣聚陀羅尼經》.md","l":22,"id":"T0946","t":"大佛頂廣聚陀羅尼經","x":"如來告金剛言：「善哉，善哉！金剛！能為一切安樂眾生諸天人眾，能為諸解法者與作因緣令得解脫，皆得三藐三菩提道，行大慈悲，能為一切世界得此法者，如烏頭摩花，與諸眾生教毘那耶，即得三藐三菩提道。」金剛聞此法已讚言：「善哉，善哉！不可思議！」復白佛言：「云何受持？云何作法，及佛頂心壇法讚族吉祥？願為解說。」"},{"p":"01-大正藏/01阿含部類/T0032《四諦經》.md","l":34,"id":"T0032","t":"四諦經","x":"「本為五陰苦，是故復說，令從是法。是法非常，厄病為壞，疾、敗、老、不堅、不信，欲、轉、離，為是故本五陰苦。過世，賢者！同是苦諦，未來世，賢者！亦是苦諦，現在世，賢者！亦是苦諦，是無有異，不倒不惑。如有諦如，是如應賢者諦賢者諦。賢者！是諦知見解得應，如是諦覺，是故名為賢者諦。"},{"p":"01-大正藏/09經集部類/T0637《佛說寶如來三昧經》.md","l":16,"id":"T0637","t":"佛說寶如來三昧經","x":"是時，羅閱國及竹園四面廣縱，上到三十六天，下到無極佛剎地，悉生文陀般華；悉有九十萬億種種色，各各異，非世之明，一華有百萬葉，葉上悉有一怛薩阿竭；悉有交絡萬寶之蓋，一蓋之上各各有萬種之音樂聲相娛樂；一佛前各各有一菩薩，如文殊師利菩薩等問事。"},{"p":"01-大正藏/03般若部類/T0225《大明度經》.md","l":28,"id":"T0225","t":"大明度經","x":"善業曰：「若非意者，為有為無(師云：當學知是非意，以知非意無復想捨，即為意淨。光明者，無復塵冥矣也)？彼可得耶(彼，彼意也。可得意處不乎)？」"},{"p":"01-大正藏/05華嚴部類/T0295《大方廣佛華嚴經入法界品》.md","l":16,"id":"T0295","t":"大方廣佛華嚴經入法界品","x":"時善財童子，敬受其教，頭面作禮，繞無數匝，戀慕瞻仰，却行而退。遂往天宮，見彼童女，禮足圍繞，合掌前住，白言：「聖者！我已先發阿耨多羅三藐三菩提心，而未知菩薩云何學菩薩行、修菩薩道？我聞聖者，善能誘誨，願為我說。」"},{"p":"01-大正藏/05華嚴部類/T1734《花嚴經文義綱目》.md","l":20,"id":"T1734","t":"花嚴經文義綱目","x":"世間淨眼品者，器等三種顯曜於時，光潔照矚況於淨眼。法喻合舉，故云世間淨眼。語言理均，格類相從，故稱為品。此經有三十四品，此品建初，故稱第一，故言大方廣佛華嚴經世間淨眼品第一。餘義如下說。"},{"p":"01-大正藏/06寶積部類/T0342《佛說如幻三昧經》.md","l":24,"id":"T0342","t":"佛說如幻三昧經","x":"是諸佛世尊覩諸侍者之所啟問，默然不應。其彼世界天、龍神聲，阿須倫、迦留羅及金翅鳥、揵沓惒聲，人、非人聲，飛鳥鹿聲，風雨水聲，大海中聲，歌妓樂聲，斯等之類，蒙佛威神，悉亦寂然，無暢音者，一切諸響悉為憺怕。其諸侍者，啟問諸佛如是至三：「世尊願說！多所哀念，多所安隱、憐愍諸天及世間人，為誰威神出是輩聲，其大光明普諸佛土？」"},{"p":"01-大正藏/09經集部類/T0768《三慧經》.md","l":18,"id":"T0768","t":"三慧經","x":"當滅思想乃得道，要在不念。已滅思想，色亦滅，識亦滅。心有所念，是為四所有對，是為想——當有想、當無想、不離想、當離想。不出想，還就。當有想者，謂道想；當無想者，謂無色想；不離想者，謂不離經行想；當離想者，當離生死想；不出想，謂無道想，不出十二門；還就者，謂人生死，便不得脫。"},{"p":"01-大正藏/09經集部類/T0755《佛說淨意優婆塞所問經》.md","l":24,"id":"T0755","t":"佛說淨意優婆塞所問經","x":"佛言：「淨意！汝今當知世間眾生，所作因行有差別故，其所得果而各有異。」時，淨意兜泥耶子復白佛言：「世尊！如佛所言因果差別，願佛世尊略為開示、若廣說者。我於是義，不能解了。」佛言：「淨意！汝當諦聽如善作意，今為汝說。」是時，淨意兜泥耶子受教而聽。"},{"p":"01-大正藏/02本緣部類/T0174《菩薩睒子經》.md","l":36,"id":"T0174","t":"菩薩睒子經","x":"「王問訊盲父母：『來在山中，勞心勤苦，樹木之間，飛鳥走獸，無有侵害道人者不？在山中，寒暑隨時，現世安隱不？』盲父母言：『蒙大王厚恩，常自安隱。我有孝子名睒，常為我取百種果蓏，泉水恒自豐饒，山中風雨和調，無所乏短。我有草席可坐、果蓏可食。睒行取水，且欲來還。』"},{"p":"01-大正藏/09經集部類/T0692《佛說作佛形像經》.md","l":14,"id":"T0692","t":"佛說作佛形像經","x":"佛至拘鹽惟國。有諸樹園主，名拘翼。時國王名優填，年十四。聞佛當來，王即勅傍臣左右，皆悉嚴駕，王即行迎佛。遙見佛，心中踊躍歡喜。王即下車步，罷傍臣、左右持蓋者，王趨迎佛前，以頭面著佛足，繞佛三匝，長跪叉手，白佛言：「天上、天下人民無有能及佛者！今佛面目身體行出，光明巍巍，好乃如是，我視佛無有厭極時。今佛是天上、天下人之師也，佛慈心，所愛者多。」"},{"p":"01-大正藏/09經集部類/T0429《佛說八部佛名經》.md","l":32,"id":"T0429","t":"佛說八部佛名經","x":"「復次，東方去此佛土，有佛號慈英寂首如來、至真、等正覺，今現在說經法，世界曰無恚恨。"},{"p":"01-大正藏/09經集部類/T0523《佛說五王經》.md","l":28,"id":"T0523","t":"佛說五王經","x":"一王復言：「我所樂復異。願我父母常在，多有兄弟、妻子，羅列好衣美食，以恣其口，素琴清衣，共相娛樂，是我之樂。」"},{"p":"01-大正藏/01阿含部類/T0053《苦陰經》.md","l":28,"id":"T0053","t":"苦陰經","x":"「復次，當如見妹病苦患，若臥床上、若臥座上、若臥蔭中，痛悉著身，極苦極患，不樂命欲斷。於意云何？前好容色寧敗壞不？」"},{"p":"01-大正藏/18史傳部類/T2063《比丘尼傳》.md","l":221,"id":"T2063","t":"比丘尼傳","x":"道綜，未詳何許人也，住江陵三層寺。少不以出眾居心，長不以同物為污，賢愚之際從通而已，跡雖混成所度潛廣。以宋大明七年三月十五日夜，自練油火，關顙既然，耳目就毀，誦詠不輟。道俗咨嗟，魔正同駭，率土聞風皆發菩提心。宋徵士劉虬雅相宗敬，為製偈贊云。"},{"p":"01-大正藏/09經集部類/T0519《佛說摩達國王經》.md","l":20,"id":"T0519","t":"佛說摩達國王經","x":"時有比丘，已得羅漢道，到其國分衛，並見錄，將詣王宮門。王有馬監，令比丘養視官馬，勤苦七日。王後身自臨視軍陣，比丘見王，即於其前，輕舉飛翔上住空中，現其威神。王便恐怖，叩頭悔過：「我實愚癡，不別真偽。推問國內誰令神人為是者，今當有所治殺。」"},{"p":"01-大正藏/05華嚴部類/T0282《諸菩薩求佛本業經》.md","l":14,"id":"T0282","t":"諸菩薩求佛本業經","x":"若那師利菩薩問文殊師利菩薩：「菩薩何因，身有所行不令他人得長短、口所言不令他人得長短、心所念不令他人得長短？何緣身不法他人長短、口不說他人長短、心不念他人長短？"},{"p":"01-大正藏/05華嚴部類/T0284《佛說菩薩十住經》.md","l":14,"id":"T0284","t":"佛說菩薩十住經","x":"佛說菩薩戒十二時竟。文殊師利白佛言：「菩薩用何功德得是十住？唯願天中天分別說之。」"},{"p":"01-大正藏/07涅槃部類/T0393《迦葉赴佛般涅槃經》.md","l":16,"id":"T0393","t":"迦葉赴佛般涅槃經","x":"迦葉弟子七人，同夕得夢：其一比丘，夢見其所坐方石中央分破，樹皆根拔；復一比丘夢見四十里泉水皆乾竭，華悉零落；一比丘夢見拘羅邊坐皆傾毀；一比丘夢見閻浮利地皆傾陷；一比丘夢見須彌山崩；一比丘夢見金輪王薨；一比丘夢見日月墮地，天下失明。晨起各以所夢啟迦葉。迦葉告言：「我曹前見光明，地時大動，卿等復得是夢，佛將般泥洹。」即勅諸弟子往赴俱夷那竭國。"},{"p":"01-大正藏/18史傳部類/T2061《宋高僧傳》.md","l":58,"id":"T2061","t":"宋高僧傳","x":"暨和帝神龍元年乙巳，於東洛內道場譯《孔雀王經》，又於大福先寺出《勝光天子》、《香王菩薩呪》、《一切莊嚴王經》四部，沙門盤度讀梵文，沙門玄傘筆受，沙門大儀證文，沙門勝莊、利貞證義，兵部侍郎崔湜、給事中盧粲潤文正字，祕書監駙馬都尉楊慎交監護。帝深崇釋典，特抽叡思，製《大唐龍興三藏聖教序》。又御洛陽西門，宣示群官新飜之經。"},{"p":"01-大正藏/04法華部類/T1913《止觀義例》.md","l":45,"id":"T1913","t":"止觀義例","x":"第七喻疑顯正例者，此所學宗同稟一師，文理相承終無異解，忽遇僻者因問異答，事不獲已而徵喻之。"},{"p":"01-大正藏/06寶積部類/T0335《佛說須摩提菩薩經》.md","l":20,"id":"T0335","t":"佛說須摩提菩薩經","x":"時佛默然，即知女意。佛語須摩提：「恣所欲問，多陀竭今當為汝具解說之，事事分別，令汝歡喜。」"},{"p":"01-大正藏/08大集部類/T0405《虛空藏菩薩經》.md","l":30,"id":"T0405","t":"虛空藏菩薩經","x":"於其會中諸大菩薩，位登十住得首楞嚴三昧及一生補處者，見此相已身心安隱不驚不怖。所以者何？緣解法相自性真實，及以於如第一義空故。其餘菩薩及聲聞眾，天、龍、夜叉、乾闥婆、阿修羅、迦樓羅、緊那羅、摩睺羅伽、鳩槃茶、餓鬼、毘舍遮、富單那、迦吒富單那、人非人等，見此相已驚怖迷悶其心擾亂，各不相見亦無問處，心自思惟：「不知何緣有此異相？亦復不知是誰神力？」"},{"p":"01-大正藏/09經集部類/T0581《佛說八師經》.md","l":39,"id":"T0581","t":"佛說八師經","x":"佛言：「二謂盜竊，強劫人財。或為財主刀杖加刑，應時瓦解；或為王法收繫著獄，拷掠、榜笞，五毒並至，戮之都市，宗門灰滅。死入地獄，以手捧火，洋銅沃口，求死不得。罪竟乃出，當為餓鬼，意欲飲水，水化為膿，所欲食物，物化成炭，身常負重，眾惱自隨。或為畜生，死輒更刃，以肉供人，償其宿債。吾見盜者，其罪如此，不敢復盜。是吾二師。」"},{"p":"01-大正藏/03般若部類/T0261《大乘理趣六波羅蜜多經》.md","l":18,"id":"T0261","t":"大乘理趣六波羅蜜多經","x":"朕齋心滌慮仰味宗源，聞所未聞實為希有。然以汲引之旨流布為先，庶憑真筌永濟浮俗。聊因暇日三復斯經，雖法海甚深而波流不讓，舉其梗概照悟將來。"},{"p":"01-大正藏/04法華部類/T0269《佛說法華三昧經》.md","l":14,"id":"T0269","t":"佛說法華三昧經","x":"佛在羅閱祇耆闍崛山中，與諸尊弟子比丘千二百五十，菩薩七萬三千人，諸釋、梵不可復計，十方飛來無央數——皆神通妙達——復有他方恒邊沙諸天人及諸菩薩，如是等百億千恒沙皆來會，在佛前坐。"},{"p":"01-大正藏/02本緣部類/T0164《師子素馱娑王斷肉經》.md","l":94,"id":"T0164","t":"師子素馱娑王斷肉經","x":"一切眾生從無始來，靡不曾作父母親屬，易生鳥獸，如何忍食？夫食肉者，歷劫之中生於鳥獸，食他血肉展轉償命。若生人間專殺嗜肉，死墮阿鼻無時暫息；若人能斷一生食肉，乃至成佛無由再食。"},{"p":"01-大正藏/06寶積部類/T0331《佛說無畏授所問大乘經》.md","l":24,"id":"T0331","t":"佛說無畏授所問大乘經","x":"於是，眾會以如是事互言議已，咸悉發起廣大勝心，皆言：「我今悉於無上大乘法中趣求涅槃，不樂聲聞、緣覺之乘。」"},{"p":"01-大正藏/09經集部類/T0442《十方千五百佛名經》.md","l":26,"id":"T0442","t":"十方千五百佛名經","x":"佛言：「若善男子、善女人聞南方佛名，不懷疑結、信悟道眼執持禮拜者，於現在世中功德具足，逮得五法：一者、除去吾我，常值佛世；二者、獲尊勢轉輪聖王；三者、逮得總持執御經典，誠信無量；四者、成三十二大人之相，至得佛道眾行備悉；五者、遂五神通無所弊礙；是為五事。若有女人聞此佛名，至心禮敬，則離女身生淨佛土，神通具足，能却七百萬億劫生死之罪。"},{"p":"01-大正藏/03般若部類/T2743《持誦金剛經靈驗功德記》.md","l":14,"id":"T2743","t":"持誦金剛經靈驗功德記","x":"梁時開善寺僧藏師講說知名時有胤師。何胤之善能占相。過見謂曰藏師。須聰明為講說。信手依經藏中撰取一卷擬長壽。持乃得金剛般若。藏在房誦持三年不出。後見胤之喜而言曰師有何法改容貌。弟子所相無驗。藏云。檀越相大有驗。是時度厄難為得受持金剛般若經力如此。胤之言曰大不可思議功德果報。今得相百年餘。歲果如所說記。"},{"p":"01-大正藏/01阿含部類/T0023《大樓炭經》.md","l":22,"id":"T0023","t":"大樓炭經","x":"諸比丘白佛言：「飯已後，於講堂上共議：『可恠未曾有，是天地云何破壞？云何成就？』但共議是事耳。」"},{"p":"01-大正藏/01阿含部類/T0001《長阿含經》.md","l":14,"id":"T0001","t":"長阿含經","x":"夫宗極絕於稱謂，賢聖以之沖默；玄旨非言不傳，釋迦所以致教。是以如來出世，大教有三：約身口，則防之以禁律；明善惡，則導之以契經；演幽微，則辨之以法相。然則三藏之作也，本於殊應，會之有宗，則異途同趣矣。"},{"p":"01-大正藏/05華嚴部類/T1738《新譯華嚴經七處九會頌釋章》.md","l":77,"id":"T1738","t":"新譯華嚴經七處九會頌釋章","x":"三十九品章者，晉朝經有三十四品，更益五品，故名三十九，謂〈如來現相品〉、〈普賢三昧品〉、〈世界成就品〉、〈華藏世界品〉、〈十定品〉。晉朝經合前四云〈盧舍那佛品〉，更無〈十定品〉，故名三十四品耳。二經品名各相替，案經可見。已說偈品，處相如何？頌曰："},{"p":"01-大正藏/08大集部類/T0404《大集大虛空藏菩薩所問經》.md","l":32,"id":"T0404","t":"大集大虛空藏菩薩所問經","x":"「如是，舍利子！有世界名大莊嚴，彼中所有妙寶樓閣一切眾會皆住虛空，今此樓閣如彼所現。」"},{"p":"01-大正藏/09經集部類/T0683《佛說諸德福田經》.md","l":22,"id":"T0683","t":"佛說諸德福田經","x":"天帝白佛：「夫人種德，欲求影福，豈有良田果報無限，種絲髮之德本，獲無量之福乎？唯願天尊敷揚惠訓，令此愚曚福報無量！」"},{"p":"01-大正藏/17禪宗部類/T2001《宏智禪師廣錄》.md","l":12,"id":"T2001","t":"宏智禪師廣錄","x":"余頑愚拙疎無所可用。獨於世味淡薄。人我相輕。若可學佛者。以故自幼喜從僧遊。間遇本色道人。雖未言而意已親。殆若磁石鐵之冥契。有不可致詰者。否則雖日相從邈如也。今。"},{"p":"01-大正藏/02本緣部類/T0165《頂生王因緣經》.md","l":28,"id":"T0165","t":"頂生王因緣經","x":"「復次，彼王漸行，又見農人種蒔㲲衣種子，見已乃問諸近臣言：『此人所作名為何等？』臣白王言：『天子！此人種蒔㲲華樹種，結實取綿可成㲲衣。』王言：『我為聖王，何假人間植㲲衣種，自有天中妙㲲種子。』纔言念時，妙㲲衣種自天而降。其王即問諸人眾言：『此由何人福力所致？』人眾答言：『此由天子福力亦兼我等。』"},{"p":"01-大正藏/17禪宗部類/T2005《無門關》.md","l":14,"id":"T2005","t":"無門關","x":"紹定二年正月初五日。恭遇天基聖節。臣僧慧開。預於元年十二月初五日。印行拈提佛祖機緣四十八則。祝延今上皇帝聖躬萬歲萬歲萬萬歲。皇帝陛下。恭願聖明齊日月。叡算等乾坤。八方歌有道之君。四海樂無為之化。"},{"p":"01-大正藏/16淨土宗部類/T0367《稱讚淨土佛攝受經》.md","l":22,"id":"T0367","t":"稱讚淨土佛攝受經","x":"「又，舍利子！何因何緣，彼佛世界名為極樂？舍利子！由彼界中諸有情類，無有一切身心憂苦，唯有無量清淨喜樂，是故名為極樂世界。"},{"p":"01-大正藏/17禪宗部類/T2000《虛堂和尚語錄》.md","l":26,"id":"T2000","t":"虛堂和尚語錄","x":"祖臨際。師運庵。聲名透徹。辭廣覺。住興聖。去取分明。足張吾軍。無愧衲子。恭惟。新命虛堂和尚。得真實諦。現清淨身。與其南北兩山閑為霧隱。孰若東西二淅高作雷鳴。況此龍宮實當虹渚。大丞相親曾問我。賢邦君不妄予人。速來速來。希有希有。閭丘向前作禮。在豐干豈饒舌之人。黃梅勉為下山。代馬祖說非心之偈。"},{"p":"01-大正藏/16淨土宗部類/T0370《阿彌陀鼓音聲王陀羅尼經》.md","l":22,"id":"T0370","t":"阿彌陀鼓音聲王陀羅尼經","x":"「阿彌陀佛與聲聞俱，如來、應、正遍知，其國號曰清泰。聖王所住，其城縱廣十千由旬，於中充滿剎利之種。阿彌陀佛如來、應、正遍知，父名月上，轉輪聖王；其母名曰殊勝妙顏；子名月明。奉事弟子，名無垢稱。智慧弟子，名曰賢光。神足精勤，名曰大化。爾時，魔王名曰無勝。有提婆達多，名曰寂靜。阿彌陀佛與大比丘六萬人俱。"},{"p":"01-大正藏/01阿含部類/T0037《緣本致經》.md","l":52,"id":"T0037","t":"緣本致經","x":"「如是，比丘！賢者集勝依附明哲，奉事多聞能致信本，信本已立便得正念，正念已樹守攝諸根，根守已建登三行淨，已三清淨便四意止，四意止立便七覺意；七覺意成立，是即無為解脫度世。」"},{"p":"01-大正藏/04法華部類/T1922《釋摩訶般若波羅蜜經覺意三昧》.md","l":22,"id":"T1922","t":"釋摩訶般若波羅蜜經覺意三昧","x":"問曰：云何名為覺意三昧？何等是意？菩薩覺是意故，即得具足三摩提耶？且復諸法無量，何以但對意用覺以明三昧？"},{"p":"01-大正藏/17禪宗部類/T1988《雲門匡真禪師廣錄》.md","l":46,"id":"T1988","t":"雲門匡真禪師廣錄","x":"上堂云。大眾汝等還有鄆州針麼。若有試將來看。有麼有麼。眾無對。師云。若無散披衣裳去也。便下座。"},{"p":"01-大正藏/03般若部類/T2735《金剛般若經旨贊》.md","l":41,"id":"T2735","t":"金剛般若經旨贊","x":"經。汝今諦聽當為汝說　贊曰。此勅聽許宣也。汝今諦聽。即是勅聽。當為汝說。即是許宣。諦謂審諦。顯離三失。謂即散亂輕慢顛倒。如次猶如覆漏穢器。而即能生三種功德。謂聞思修。勝三慧也。由此方堪聽受正法。故智度論所說偈云。聽者端示如飢渴一心。入於語義中。聞法踊躍心悲喜。如是之人可為說。故先勅聽。方復許宣。"},{"p":"01-大正藏/10密教部類/T0873《金剛頂蓮華部心念誦儀軌》.md","l":48,"id":"T0873","t":"金剛頂蓮華部心念誦儀軌","x":"「唵薩嚩怛他(（引）)誐多布儒(（引）)波薩他(（二合）)曩也(（引）)怛摩(二合（引）)喃儞哩耶(（二合）)多夜(（引）)弭薩嚩怛他(（引）)誐多嚩日囉(二合)薩怛嚩(二合（引）)地瑟咤(二合)娑嚩(二合)𤚥吽」"},{"p":"01-大正藏/04法華部類/T1925《法界次第初門》.md","l":12,"id":"T1925","t":"法界次第初門","x":"天台山修禪寺沙門釋智顗，輒依經附論，撰《法界次第初門》三百科，裁為七卷，流傳新學。略為三意：一、為讀經尋論隨見法門，脫有迷於名數者；二、為未解聖教所制法門淺深之次第；三、為學三觀之者，當以此諸法名相義理，一一歷心而轉作，則觀解無礙，觸境不迷。若於一念心中通達一切佛法者，則三觀自然了了分明也。故出此三百科名教，仍當名下略辨體相，始得三卷。"},{"p":"01-大正藏/07涅槃部類/T0390《佛臨涅槃記法住經》.md","l":24,"id":"T0390","t":"佛臨涅槃記法住經","x":"「我涅槃後第二百年，吾聖教中寂靜堅固，我諸弟子聰慧多聞，如天人師，具大威德多所饒益；以是義故，天龍歡喜常加守護，國王大臣、長者居士亦復如是，善識福田，於佛、法、僧深生淨信，供養恭敬尊重讚歎。"},{"p":"01-大正藏/09經集部類/T0669《佛說無上依經》.md","l":20,"id":"T0669","t":"佛說無上依經","x":"佛言：「善哉，善哉！阿難！能問如來如此大事，汝能修行眾多利益，憐愍世間作歸依處，能令人天得道安樂，能拔眾生不住苦地。是故阿難！汝今諦聽，專思念之，敬心信受。」"},{"p":"01-大正藏/09經集部類/T0639《月燈三昧經》.md","l":20,"id":"T0639","t":"月燈三昧經","x":"佛言：「童子！隨汝所樂，於彼彼問當為汝說，令得歡喜。我一切智、一切知見，於一切法有力、無畏而得自在，與無障礙解脫知見相應。童子！如來無所不知、無所不見、無所不證、無不選擇，覺知無量無邊世界。童子！諸佛、世尊於彼彼問悉能隨答，皆令心喜。」"},{"p":"01-大正藏/03般若部類/T0252《普遍智藏般若波羅蜜多心經》.md","l":20,"id":"T0252","t":"普遍智藏般若波羅蜜多心經","x":"於是觀自在菩薩摩訶薩蒙佛聽許，佛所護念，入於慧光三昧正受。入此定已，以三昧力行深般若波羅蜜多時，照見五蘊自性皆空。彼了知五蘊自性皆空，從彼三昧安詳而起。即告慧命舍利弗言：「善男子！菩薩有般若波羅蜜多心，名普遍智藏。汝今諦聽，善思念之。吾當為汝分別解說。」作是語已。慧命舍利弗白觀自在菩薩摩訶薩言：「唯，大淨者！願為說之。今正是時。」"},{"p":"01-大正藏/01阿含部類/T0066《魔嬈亂經》.md","l":20,"id":"T0066","t":"魔嬈亂經","x":"「汝波旬！汝所念，我亦知之。汝所作念：『沙門不知不見，而作此言：「波旬！出！波旬！出！莫觸嬈如來及如來弟子，莫於長夜遭無量苦，無義饒益。」謂彼世尊，有如是力，如是有所能，彼猶不能知我見我，況復弟子，能知見我？是事不然！』」"},{"p":"01-大正藏/05華嚴部類/T1866《華嚴一乘教義分齊章》.md","l":20,"id":"T1866","t":"華嚴一乘教義分齊章","x":"初中二：一、性海果分，是不可說義。何以故？不與教相應故，則十佛自境界也。故《地論》云：因分可說，果分不可說者是也。"},{"p":"01-大正藏/06寶積部類/T0341《聖善住意天子所問經》.md","l":12,"id":"T0341","t":"聖善住意天子所問經","x":"夫法留正像，唯聖是依；季行此世，非賢豈伏？三藏法師毘目智仙，出自烏萇剎利王種，幼履慈蹤，長躡悲跡，攝化群迷，誡惡導善，常為眾生不請之友，執此法燈照彼昏闇。魏皇都鄴，崇福以資，興和二年歲次實沈，佛法加持出此經典，名「善住意天子所問」。建午閏月朔次丁丑，戊寅建功，乙巳畢功。助譯弟子瞿曇流支、對譯沙門曇林之筆，庶俟存道敬法之賢，如實印記，示令不惑耳。"},{"p":"01-大正藏/09經集部類/T0609《禪要經》.md","l":20,"id":"T0609","t":"禪要經","x":"又念我身，以骨為柱、以肉為泥、筋纏血澆，如瘡如毒，皮毛九孔以為門戶，腸胃胞膜以為庫藏，妬慢惡心謂以為身，貪求無厭猶如溪壑。是故行者除三欲想，受信施時，如火毒想，救諸蟲想，繫死屍想，涎沫、齒垢、污滋味想，我無空慧壞白淨想，貪愛因緣成惡露想。如是思惟，慚愧具足，能度生死、為世福田。"},{"p":"01-大正藏/08大集部類/T0419《拔陂菩薩經》.md","l":16,"id":"T0419","t":"拔陂菩薩經","x":"佛在羅悅祇竹園多鳥樹下，與眾弟子五百比丘俱，皆是阿羅漢，所著盡，無餘結，所作滿，所求具，皆已下重擔，悉至所願，已斷於故胎，從政化度，皆悉度八禪，除一凡比丘。"},{"p":"01-大正藏/09經集部類/T0651《佛說諸法本無經》.md","l":168,"id":"T0651","t":"佛說諸法本無經","x":"「善家子！彼金焰影世界，若樹若柱，彼皆七寶所成。彼樹出如是聲，所謂：空聲、無相聲、無願聲、無生聲、無所有聲、無相貌聲，彼出如是等聲。於中如是等聲出時，彼諸眾生其心解脫。彼如來滅度千歲正法住已，彼聲亦不復出。"},{"p":"01-大正藏/16淨土宗部類/T1968《往生淨土決疑行願二門》.md","l":20,"id":"T1968","t":"往生淨土決疑行願二門","x":"第一決疑門者，疑為信障，世間小善尚不能成，況菩提大道乎。或曰：天台智者已有《釋十疑論》，何須此文？然略由三意："},{"p":"01-大正藏/10密教部類/T0986《大金色孔雀王呪經》.md","l":24,"id":"T0986","t":"大金色孔雀王呪經","x":"「那羅延波那延　阿梨多利　鳩多利伊利彌悉帝　吉帝利　彌悉帝　彌悉伊利彌呪曰成就吉」"},{"p":"01-大正藏/09經集部類/T0588《佛說須真天子經》.md","l":26,"id":"T0588","t":"佛說須真天子經","x":"佛言：「善哉，善哉！須真天子！所問甚深，多所過度於世人民，念持是事以問如來，起菩薩意濟脫生死。諦聽，諦受！佛當為汝解說其義，踰於所問，疾得是事。」於是天子受教而聽。"},{"p":"01-大正藏/05華嚴部類/T1737《大華嚴經略策》.md","l":34,"id":"T1737","t":"大華嚴經略策","x":"又問言帶前赴後事理應齊，何以三賢獨有斯旨者，顯異義故。謂初二會相隣次故不假帶前，此三人天隔越故須連帶。又此三會同詮賢位，六已證入不假帶前，第七即位中普賢及於妙覺居然不假，第八頓彰六位體用已融，第九唯明證入體用一味，故竝皆不假。唯三會要令成鉤鎖一法界會故。謹對。"},{"p":"01-大正藏/07涅槃部類/T1768《涅槃經遊意》.md","l":14,"id":"T1768","t":"涅槃經遊意","x":"就此經有南北二本，廣略不同，北方舊本，卷或有三十三，或三十者，品唯有十三。南土文，卷有三十六，有二十五品。"},{"p":"01-大正藏/09經集部類/T0458《文殊師利問菩薩署經》.md","l":16,"id":"T0458","t":"文殊師利問菩薩署經","x":"佛言：「善哉！善哉！舍利弗當問。汝若從文殊尸利，但聞怛薩阿竭署因緣法名，未悉得其事，今為汝說之。諦聽！諦聽！」"},{"p":"01-大正藏/09經集部類/T0644《佛說金剛三昧本性清淨不壞不滅經》.md","l":30,"id":"T0644","t":"佛說金剛三昧本性清淨不壞不滅經","x":"「彌勒當知！此百三昧，從道種智、十波羅蜜生，安隱不去，亦復不住寂靜無為，住爾焰地。此爾焰地不熏不修，自然當得八萬四千諸三昧門。此諸三昧，如金剛山不可沮壞，畢竟住於大空邊際，亦復遊入無相法界，於諸法中，不見來去及住滅相。其心寂然，即得超入金剛三昧。此金剛三昧，如梵王頂上因陀羅寶珠，不見色相而有光明；金剛三昧，不見使海及使邊際。"},{"p":"01-大正藏/06寶積部類/T0346《佛說大方廣善巧方便經》.md","l":20,"id":"T0346","t":"佛說大方廣善巧方便經","x":"彼時會中有一菩薩摩訶薩名曰智上，從座而起，偏袒右肩，右膝著地，禮佛雙足。禮已合掌，前白佛言：「世尊！我有少法欲伸請問如來、應供、正等正覺，悲愍我故，願賜聽許。」"},{"p":"01-大正藏/06寶積部類/T0319《大聖文殊師利菩薩佛剎功德莊嚴經》.md","l":20,"id":"T0319","t":"大聖文殊師利菩薩佛剎功德莊嚴經","x":"復有六萬二千諸大龍王，所謂難陀龍王、鄔波難陀龍王、水天龍王、摩那斯龍王、地持龍王、無熱惱龍王、蘇迷盧龍王、伏魔龍王、月上龍王，如是等而為上首。"},{"p":"01-大正藏/01阿含部類/T0052《大生義經》.md","l":22,"id":"T0052","t":"大生義經","x":"「復次，有法以何為緣？所謂取法為緣。由取法故即起有法；取法若無有法何得？阿難！當知此取法者，即虛妄法而不究竟，此集此因此生此緣得起有法，由是有法亦不究竟。"},{"p":"01-大正藏/09經集部類/T0746《餓鬼報應經》.md","l":14,"id":"T0746","t":"餓鬼報應經","x":"尊者大目揵連，從佛在耆闍崛山中，遊行恒水邊，見諸餓鬼甚多，受罪不同。見尊者目連，皆起敬心，來問因緣。"},{"p":"01-大正藏/09經集部類/T0607《道地經》.md","l":20,"id":"T0607","t":"道地經","x":"說生老病死著意憂，便身生苦已，欲度世者，便行道地，莫厭在身。已有老病死，從是若著意惱生，欲隨受佛戒者，便行從致無為。"},{"p":"01-大正藏/09經集部類/T0623《佛說如來獨證自誓三昧經》.md","l":46,"id":"T0623","t":"佛說如來獨證自誓三昧經","x":"於是座中有眼見光賢菩薩，即起正衣服，偏露右臂下右膝，長跪叉手前白聖師：「願有所問。唯聖師以無量慧照釋未聞。」答曰：「善哉！恣汝所問。今當為汝具敷大要。」"},{"p":"01-大正藏/10密教部類/T1075《佛說七俱胝佛母准提大明陀羅尼經》.md","l":24,"id":"T1075","t":"佛說七俱胝佛母准提大明陀羅尼經","x":"「或以淨瓦鉢燒香熏之，內外塗香，盛滿香水并好香花置曼茶羅中，依前瓶法而作念誦，其鉢則轉與瓶無異。"},{"p":"01-大正藏/09經集部類/T0511《佛說蓱沙王五願經》.md","l":20,"id":"T0511","t":"佛說蓱沙王五願經","x":"蓱比沙王與弗迦沙王生未曾相見，遙相愛敬如兄弟，常書記往來，相問遺不絕。蓱比沙王意常念：「令我得絕奇好物，以遺弗迦沙。」弗迦沙王亦常意念：「令我得絕奇好物，以遺蓱比沙王。」"},{"p":"01-大正藏/02本緣部類/T0188《異出菩薩本起經》.md","l":14,"id":"T0188","t":"異出菩薩本起經","x":"釋迦文佛前世宿命為人時，在夫婁多摩國，世世為善，無數世乃得為佛。佛為菩薩時，名摩納，居山中，衣鹿皮衣。"},{"p":"01-大正藏/09經集部類/T0793《佛說佛醫經》.md","l":16,"id":"T0793","t":"佛說佛醫經","x":"三月、四月、五月、六月、七月得臥。何以故？風多故身放。八月、九月、十月、十一月、十二月、正月、二月不得臥。何以故？寒多故身縮。"},{"p":"01-大正藏/01阿含部類/T0072《三歸五戒慈心厭離功德經》.md","l":18,"id":"T0072","t":"三歸五戒慈心厭離功德經","x":"「如上布施及受三歸福，復不如受五戒福。受五戒者，功德滿具，其福勝也。如上布施及受三歸、五戒福，復不如彈指頃慈念眾生福也。如上布施，及受三歸、五戒，慈念眾生福，復不如起一切世間不可樂想福。所以然者，起一切世間不可樂想福，能令行者滅生死苦，終成佛道，故其福最勝也。」"},{"p":"01-大正藏/01阿含部類/T0040《文陀竭王經》.md","l":20,"id":"T0040","t":"文陀竭王經","x":"「在俱耶尼國數千歲，王復生意：『我有大國在西方，名俱耶尼，縱廣三十二萬里，我有七寶，天為我雨錢金銀七日七夜，我有千子，皆端正無比高才健猛力壯，我有南方閻浮提國二十八萬里。』王聞東方有弗于逮國，人民熾盛，穀米平賤，其國大樂。王意欲往，適生意，便舉七寶、四種兵俱飛行到，其國王及人民便降伏屬之，王因以正法治國。"},{"p":"01-大正藏/01阿含部類/T0046《阿那律八念經》.md","l":26,"id":"T0046","t":"阿那律八念經","x":"「比丘隱處，謂避人間，不入眾會，遠居山澤巖石樹間。如有四輩，若王大臣來從問道，為說清淨欲令疾去。譬如貧人負豪姓債，為主所牽抴，欲離不樂潛隱遠遁，義當從是。"},{"p":"01-大正藏/01阿含部類/T0033《恒水經》.md","l":30,"id":"T0033","t":"恒水經","x":"佛言：「諸弟子！天下有五江，東流一江字沙祿，南流一江字阿夷，西流一江字恒，北流一江字默徘徊，中流名字為江；轉流入海皆棄本名字，當為海水。」"},{"p":"01-大正藏/09經集部類/T0806《佛說枯樹經》.md","l":20,"id":"T0806","t":"佛說枯樹經","x":"集訖，諸王於其處，造僧伽藍，名諸王寺，在偷婆北。後群茶王，慊偷婆當城門，王欲壞之，勅城內嚴銚䤺，明當除之。夜半偷婆便移，從城上過，音聲振國，去城南二十里，在林樹間止。所勸王破寺臣者，即誅五族。王覩變知改，為清信士。自移來，可四十年許。諸王寺朽壞，後有橫王出，更修飾之，今日現在。"},{"p":"01-大正藏/01阿含部類/T0078《兜調經》.md","l":38,"id":"T0078","t":"兜調經","x":"佛言：「但坐所知自貢高，故作狗耳。汝欲知審是汝父不？還歸於家，語狗言：『汝審是我父兜調者，當於故器中食。汝審是我父者，當還於故處臥。汝審是我父者，先時所有珍寶藏物當示我處。』」"},{"p":"01-大正藏/01阿含部類/T0039《頂生王故事經》.md","l":20,"id":"T0039","t":"頂生王故事經","x":"「爾時，阿難！王頂生於彼治化無數百千歲。是時，阿難！大王頂生，復於異時便作是念：『我有閻浮利地，所欲自在神足，穀茂豐熟人民繁稠。我已雨七寶於宮殿乃至七日，今復有弗于逮境界自在神足，穀茂豐熟人民繁稠。我曾聞，曩昔舊人聰明黠慧，便作是語：「有瞿耶尼國土神足自在，穀茂豐熟人民繁稠。」』王便作是念：『我欲往至瞿耶尼界率化人民。』"},{"p":"01-大正藏/09經集部類/T0494《阿難七夢經》.md","l":16,"id":"T0494","t":"阿難七夢經","x":"佛時在舍衛國普會講堂上，與波斯匿王說法：苦、習、滅、得道為樂。見阿難憂色愁苦叵言，佛告阿難：「汝於夢者，皆為當來五濁惡世，不損汝也，何為憂色？"},{"p":"01-大正藏/02本緣部類/T0178《前世三轉經》.md","l":20,"id":"T0178","t":"前世三轉經","x":"賢者阿難，時知七法事，何等為七？一者、知義；二者、解法；三者、曉時；四者、了節；五者、明眾；六者、知身事；七者、知他人事。賢者阿難從座起，整衣被長跪叉手，以偈讚佛言："},{"p":"01-大正藏/07涅槃部類/T0384《菩薩從兜術天降神母胎說廣普經》.md","l":28,"id":"T0384","t":"菩薩從兜術天降神母胎說廣普經","x":"「云何？阿難！吾於龍宮與龍說法，無數億千諸龍子等皆令得道，留全身舍利百三十丈，汝亦知不？」"},{"p":"01-大正藏/03般若部類/T2742《金剛般若波羅蜜經傳外傳卷下》.md","l":34,"id":"T2742","t":"金剛般若波羅蜜經傳外傳卷下","x":"原夫諸佛降靈懸遠難遇。設使逢遇聞法更難。設得聞法聞深又難。設聞深法信解彌難。設能信解悟入最難。此則悟入不悟入。在於精懃不精懃不在聞說也。願同修住者無自輕烏無自棄烏如頌云。"},{"p":"01-大正藏/01阿含部類/T0006《般泥洹經》.md","l":24,"id":"T0006","t":"般泥洹經","x":"「又比丘有七守，則法不衰，當善念行：一守清淨，不樂有為。二守無欲，不貪利養。三守忍辱，無所諍訟。四守空行，不入眾聚。五守法意，不起眾想。六守一心，坐禪定意。七守約損，衣食麁踈，草蓐為床。如是七法，可得久住。"},{"p":"01-大正藏/16淨土宗部類/T1958《安樂集》.md","l":20,"id":"T1958","t":"安樂集","x":"又彼經云：「諸佛出世，有四種法度眾生。何等為四？一者、口說十二部經，即是法施度眾生；二者、諸佛如來有無量光明、相好，一切眾生但能繫心觀察，無不獲益，是即身業度眾生；三者、有無量德用、神通、道力，種種變化，即是神通力度眾生；四者、諸佛、如來有無量名號，若總、若別，其有眾生繫心稱念，莫不除障獲益，皆生佛前，即是名號度眾生。」"},{"p":"01-大正藏/04法華部類/T0264《添品妙法蓮華經》.md","l":28,"id":"T0264","t":"添品妙法蓮華經","x":"菩薩摩訶薩八萬人，皆於阿耨多羅三藐三菩提不退轉，皆得陀羅尼，樂說辯才，轉不退轉法輪。供養無量百千諸佛，於諸佛所，殖眾德本，常為諸佛之所稱歎。以慈修身，善入佛慧。通達大智到於彼岸。名稱普聞無量世界，能度無數百千眾生。"},{"p":"01-大正藏/18史傳部類/T2060《續高僧傳》.md","l":63,"id":"T2060","t":"續高僧傳","x":"闍那崛多。隋言德志北賢豆　賢豆。本音因陀羅婆陀那。此云主處。謂天帝所護故也。賢豆之音。彼國之訛略耳。身毒天竺。此方之訛稱也。而彼國人。總言賢豆而已。乃之以為五方也。"},{"p":"01-大正藏/01阿含部類/T0058《阿耨風經》.md","l":18,"id":"T0058","t":"阿耨風經","x":"「我記禘婆達兜當墮惡趣，泥犁中住一劫，難可救。何以故？唯，世尊！豈不聞此耶？唯世尊！我從一比丘聞此言。」"},{"p":"01-大正藏/10密教部類/T0914《火吽軌別錄》.md","l":72,"id":"T0914","t":"火吽軌別錄","x":"凡持誦不動尊真言，皆須作壇，壇法即後樣是。皆以青色、黑色花，燒沈香、安息香，隨時果子、飲食、燈火、香水供養。欲供養時，行者澡浴著新衣，先誦本尊真言，結本尊印，以杓取香水灑諸供養物，然後供養，名為淨護，即諸魔不能穢惡。兼用虛空庫心供養法，最不可思議。布置供養具訖，即誦三昧耶真言，辟除結界。"},{"p":"01-大正藏/01阿含部類/T0025《起世因本經》.md","l":20,"id":"T0025","t":"起世因本經","x":"是時，世尊獨在靜窟，天耳徹聽清淨過人，聞諸比丘飯食已後，皆出聚集迦利囉堂，共作如是希有語言。世尊聞已，其日晡時出於禪定，從迦利囉窟中而起，行詣堂上。到堂上已，在諸比丘大眾之前，依常敷座，儼然端坐。世尊坐已，知而故問：「汝等比丘，向者議論說何語言，聚集而坐？」"},{"p":"01-大正藏/01阿含部類/T0030《薩鉢多酥哩踰捺野經》.md","l":20,"id":"T0030","t":"薩鉢多酥哩踰捺野經","x":"「復次，苾芻！劫相末時五日出現，炎照世間，熱相盛前，大地所有大海之水，漸漸減少，一百由旬、二百由旬、三百由旬至一千由旬；日既炎盛天雨彌愆，海又復減至二千由旬、三千由旬乃至七千由旬，如是減已，海中餘水亦有七千由旬。"},{"p":"01-大正藏/04法華部類/T0276《無量義經》.md","l":36,"id":"T0276","t":"無量義經","x":"其比丘名曰：大智舍利弗、神通目揵連、慧命須菩提、摩訶迦旃延、彌多羅尼子富樓那、阿若憍陳如等，天眼阿那律、持律憂波離、侍者阿難、佛子羅云、憂波難陀、離婆多、劫賓那、薄拘羅、阿周陀、莎伽陀、頭陀大迦葉、憂樓頻螺迦葉、伽耶迦葉、那提迦葉。如是等比丘萬二千人，皆阿羅漢，盡諸結漏，無復縛著，真正解脫。"},{"p":"01-大正藏/02本緣部類/T0162《金色王經》.md","l":24,"id":"T0162","t":"金色王經","x":"「復於異時有惡星現，應十二年天不降雨。有婆羅門善知相術，善知咒論，知太白等眾星行度。既見惡星，占相知已詣金色王，既到王所具為王說，作如是言：『天今當知惡星已出，於天不祥，應十二年天不降雨。』"},{"p":"01-大正藏/02本緣部類/T0161《長壽王經》.md","l":20,"id":"T0161","t":"長壽王經","x":"「長壽王乃謂其太子曰：『彼貪我國，故來攻我。今群臣以我故，欲逆而距之。夫兩敵相向，必有缺傷，今欲與汝俱委國亡去。』太子言：『諾。』即父子共踰城而出，幽隱山間。"},{"p":"01-大正藏/08大集部類/T0412《地藏菩薩本願經》.md","l":20,"id":"T0412","t":"地藏菩薩本願經","x":"出如是等不可說不可說音已，娑婆世界及他方國土，有無量億天龍鬼神，亦集到忉利天宮。所謂四天王天、忉利天、須焰摩天、兜率陀天、化樂天、他化自在天、梵眾天、梵輔天、大梵天、少光天、無量光天、光音天、少淨天、無量淨天、遍淨天、福生天、福愛天、廣果天、無想天、無煩天、無熱天、善見天、善現天、色究竟天、摩醯首羅天，乃至非想非非想處天，一切天眾、龍眾、鬼神等眾，悉來集會。"},{"p":"01-大正藏/02本緣部類/T0180《過去世佛分衛經》.md","l":16,"id":"T0180","t":"過去世佛分衛經","x":"「有一母人姙身數月，見佛及僧有所至奏，心自計願：『我所懷子生，如此使為沙門佛弟子。』日月滿足即生安隱，兒亦姝好與眾人異，母以恩愛無意令兒行作沙門，中有覺意，即自念言：『我前有願，若我生子當使為道。兒今已生，有異凡人——令我安隱——復無惡露，不可戀嫪恩愛之故，違我本心。』"},{"p":"01-大正藏/04法華部類/T0272《大薩遮尼乾子所說經》.md","l":24,"id":"T0272","t":"大薩遮尼乾子所說經","x":"復有摩訶波闍波提比丘尼、耶輸陀羅比丘尼等八千比丘尼，於百千萬億比丘尼中而為上首。一切皆悉具足善集諸妙白法，一切善入一切智道，一切皆近一切智智，一切皆入無所有性，一切能觀諸法無相，一切善信法際無際，一切皆得無障解脫，一切皆得隨諸有緣，可化眾生示佛色身。"},{"p":"01-大正藏/06寶積部類/T0336《須摩提經》.md","l":18,"id":"T0336","t":"須摩提經","x":"時王舍城有長者女名為妙慧，年始八歲，面貌端正，容色姝好，諸相具足，見者歡喜——曾於過去無量諸佛親近供養、種諸善根。"},{"p":"01-大正藏/06寶積部類/T0311《大方廣三戒經》.md","l":22,"id":"T0311","t":"大方廣三戒經","x":"復有五百比丘尼，其名曰摩訶波闍波提比丘尼、安隱比丘尼、蓮華比丘尼、極苦瞿曇彌比丘尼、羅睺羅母耶輸陀羅比丘尼，是等上首五百比丘尼俱。"},{"p":"01-大正藏/07涅槃部類/T0392《佛滅度後棺斂葬送經》.md","l":32,"id":"T0392","t":"佛滅度後棺斂葬送經","x":"「王亡尊鉢，憂忿交胸，布告諸國，購鉢千金。連年募之，令出首尾。民貪重賞，遍索不得。時有賤人，其名曰師，偽作比丘，饕餮酒食，妻居育子。當醉提兒詣宮門言：『吾知鉢處。』王聞大喜，請沙門入，曰：『鉢所在乎？』對曰：『先以金來。』王賜金千斤。師曰：『唯沙門當盜之耳。』即下書考推諸沙門，其毒酷烈，臣民覩之靡不怨王。王曰：『爾為誰沙門乎？』答曰：『吾師事佛。』王曰：『佛有何戒耶？』師曰：『有二百五十戒。』"},{"p":"01-大正藏/02本緣部類/T0167《太子慕魄經》.md","l":20,"id":"T0167","t":"太子慕魄經","x":"「王唯有此一子耳，舉國人民皆重愛之，當繼後嗣襲續王位；然以追識宿命，億載存亡禍福，故質不語至十三歲，捐棄形骸，志存虛無，漂漂不說，飢寒恬淡，質朴意如枯木——雖有耳目，不存視聽；智慮雖遠，如無心志；不畏污辱，亦無憎愛；若盲若聾，不說西東；狀如矇聵，不與人同。"},{"p":"01-大正藏/05華嚴部類/T0285《漸備一切智德經》.md","l":26,"id":"T0285","t":"漸備一切智德經","x":"時彼會中有一菩薩，名月解脫，亦來俱會。時月解脫菩薩大士，知彼眾會開士所念，以偈歎頌，問金剛藏此義所歸："},{"p":"01-大正藏/01阿含部類/T0079《鸚鵡經》.md","l":28,"id":"T0079","t":"鸚鵡經","x":"答曰：「摩牢！我晨起著衣服已，與衣鉢俱詣舍衛城分衛，遊舍衛城分衛時便至汝家。汝白狗遙見我從遠而來，見已而吠，我便作是言：『止！白狗！汝不應作是聲，汝本吟哦！』是故，摩牢！彼白狗則瞋恚不樂，下牀褥已依門閾默然伏。」"},{"p":"01-大正藏/08大集部類/T0398《大哀經》.md","l":22,"id":"T0398","t":"大哀經","x":"大比丘眾六百萬人，一切人民——滅除塵欲，無眾蔽礙——則為如來法王之子，行深妙法。其所由生不從顛倒，柔軟和雅，威儀禮節而皆備悉，為大眾祐如來之道而得親近。"},{"p":"01-大正藏/07涅槃部類/T0389《佛垂般涅槃略說教誡經》.md","l":24,"id":"T0389","t":"佛垂般涅槃略說教誡經","x":"「汝等比丘，當自摩頭，已捨飾好著壞色衣，執持應器以乞自活，自見如是，若起憍慢當疾滅之。謂長憍慢尚非世俗白衣所宜，何況出家入道之人為解脫故，自降其心而行乞耶？"},{"p":"01-大正藏/09經集部類/T0758《佛說諸行有為經》.md","l":22,"id":"T0758","t":"佛說諸行有為經","x":"「若彼三界漏盡，已作所作，遠離重擔，逮得己利，盡諸有結，得阿羅漢，雖復此身亦當棄捨；又彼刀兵劫，自修一身處於寂靜，悟諸因緣得中乘證，號辟支佛；雖復此身亦當棄捨；乃至如來、應、正等覺，十力廣大，四智圓明，說法無畏，正師子吼，歷無數勤勞得那羅延身，亦復棄捨。"},{"p":"01-大正藏/17禪宗部類/T1990《袁州仰山慧寂禪師語錄》.md","l":18,"id":"T1990","t":"袁州仰山慧寂禪師語錄","x":"耽源上堂，師出眾作此○相，以手拓呈了，却叉手立。耽源以兩手相交作拳示之，師進前三步作女人拜。耽源點頭，師便禮拜。師浣衲次，耽源云：「正恁麼時作麼生？」師云：「正恁麼時向甚麼處見。」"},{"p":"01-大正藏/10密教部類/T0901《陀羅尼集經》.md","l":16,"id":"T0901","t":"陀羅尼集經","x":"三月上旬赴慧日寺浮圖院內，法師自作普集會壇，大乘琮等一十六人，爰及英公、鄂公等一十二人，助成壇供，同願皇基永固，常臨萬國，庶類同沾，皆成大益，其中靈瑞恐繁不述(別在傳記)。"},{"p":"01-大正藏/16淨土宗部類/T1971《淨土境觀要門》.md","l":18,"id":"T1971","t":"淨土境觀要門","x":"問：約心觀佛，唯是所觀境，亦含能觀觀耶？答：觀之一字是能觀觀，心佛二字是所觀境。若爾，此所觀境是妄耶？是真耶？答：一家所論境觀，永異諸說。直觀真心真佛唯屬佛界，是故凡曰觀心觀佛皆屬妄境，意在了妄即真，不須破妄然後顯真。諸家直觀真者，妄必須破，真理方顯。此乃緣理斷九之義，正是破九界修惡、顯佛界性善，是斷滅法，乃屬偏前別教，非是圓頓妙觀。"},{"p":"01-大正藏/06寶積部類/T0339《得無垢女經》.md","l":18,"id":"T0339","t":"得無垢女經","x":"寶明菩薩、慧聚菩薩、勝藏菩薩、名稱意菩薩、辯聚菩薩、觀世自在菩薩、得大勢菩薩、彌勒菩薩、得無憂菩薩、文殊師利童子菩薩、不迷行菩薩、不迷見菩薩、除惡菩薩、壞一切悲闇菩薩、功德寶華莊嚴菩薩、金纓光德菩薩、障一切罪菩薩、不壞思惟菩薩，如是等上首，十千菩薩俱。"},{"p":"01-大正藏/17禪宗部類/T1996《明覺禪師語錄》.md","l":24,"id":"T1996","t":"明覺禪師語錄","x":"上堂。問答罷。師乃云。釋迦已滅彌勒未生。正當今日。佛法委在翠峯。放開揑聚總由者裏。放開也七縱八橫。是處填溝塞壑。揑聚也天下老和尚。盡在拄杖頭。不消一劄。"},{"p":"01-大正藏/04法華部類/T0265《薩曇分陀利經》.md","l":16,"id":"T0265","t":"薩曇分陀利經","x":"佛在羅閱祇耆闍崛山中，與大比丘眾四萬二千人俱。三慢陀颰陀、文殊師利菩薩等，八萬四千人；彌勒菩薩等，拔陀劫中千人。釋王等，與忉利諸天不可復計；梵王，與諸梵不可復計。阿闍世王，與閻浮提人王眾多不可復計。"},{"p":"01-大正藏/10密教部類/T1091《七星如意輪祕密要經》.md","l":61,"id":"T1091","t":"七星如意輪祕密要經","x":"天明五乙巳春二月十日，於洛北大報恩寺，以上品蓮臺寺藏本寫訖。此七星如意輪經，於重譽深密抄薄草子後重等證之。"},{"p":"01-大正藏/02本緣部類/T0163《妙色王因緣經》.md","l":22,"id":"T0163","t":"妙色王因緣經","x":"世尊告曰：「汝等苾芻！我於往昔為求法故，敬心殷重。汝等諦聽！善思念之！吾當為汝說彼因緣。"},{"p":"01-大正藏/05華嚴部類/T0279《大方廣佛華嚴經》.md","l":16,"id":"T0279","t":"大方廣佛華嚴經","x":"朕曩劫植因，叨承佛記。金仙降旨，大雲之偈先彰；玉扆披祥，寶雨之文後及。加以積善餘慶，俯集微躬，遂得地平天成，河清海晏。殊禎絕瑞，既日至而月書；貝牒靈文，亦時臻而歲洽。逾海越漠，獻賝之禮備焉；架險航深，重譯之辭罄矣。"},{"p":"01-大正藏/09經集部類/T0730《佛說處處經》.md","l":14,"id":"T0730","t":"佛說處處經","x":"佛言：「道人行道，若瞋恚意起時，即當制己，制便念善，是為道人行。若布施財利，得之便計無常，不隨身犯，謂不犯殺盜婬，是為不隨身犯。出瞋恚者口亦不言，意亦不念，是為出瞋恚意中大深聲者。譬如人作盜，說言：『汝所作大無狀。』是為意中大深聲。」"},{"p":"01-大正藏/02本緣部類/T0183《一切智光明仙人慈心因緣不食肉經》.md","l":18,"id":"T0183","t":"一切智光明仙人慈心因緣不食肉經","x":"時有迦波利婆羅門子，名彌勒——軀體金色，三十二相，八十種好，放銀光明，黃金校飾，如白銀山，威光無量——來至佛所。"},{"p":"01-大正藏/09經集部類/T0594《佛說大自在天子因地經》.md","l":24,"id":"T0594","t":"佛說大自在天子因地經","x":"大自在天白言：「此是大福德離欲佛弟子，能破諸過，教化眾生與作安樂，因為乞食而來至此。」"},{"p":"01-大正藏/02本緣部類/T0159《大乘本生心地觀經》.md","l":22,"id":"T0159","t":"大乘本生心地觀經","x":"復有億萬六欲天子，其名曰：善住天子、威德天子、普光天子、清淨慧天子、吉祥天子、大吉祥天子、自在天子、大自在天子、日光天子、月光天子。如是等天子，釋提桓因而為上首，悉皆愛樂大乘妙法，願隨奉事三世如來，入不思議祕密境界，莊嚴諸佛眾會道場；各與若干百千眷屬俱。"},{"p":"01-大正藏/06寶積部類/T0348《佛說大乘方等要慧經》.md","l":22,"id":"T0348","t":"佛說大乘方等要慧經","x":"彌勒問言：「云何菩薩摩訶薩不退轉法，於大乘有進而不耗減，行菩薩道並降伏魔怨，如其狀貌，悉還教知諸法根之相，不厭於生死，自有正慧不從他受，疾成無上一切智地？」"},{"p":"01-大正藏/04法華部類/T1924《大乘止觀法門》.md","l":32,"id":"T1924","t":"大乘止觀法門","x":"就廣分別，止觀門中作五番建立：一明止觀依止、二明止觀境界、三明止觀體狀、四明止觀斷得、五明止觀作用。"},{"p":"01-大正藏/05華嚴部類/T0297《普賢菩薩行願讚》.md","l":168,"id":"T0297","t":"普賢菩薩行願讚","x":"每日誦普賢菩薩行願讚後，即誦此真言，纔誦一遍，普賢行願悉皆圓滿，三摩地人，速得三昧現前，福德智慧，二種莊嚴，獲堅固法，速疾成就。"},{"p":"01-大正藏/03般若部類/T0250《摩訶般若波羅蜜大明呪經》.md","l":16,"id":"T0250","t":"摩訶般若波羅蜜大明呪經","x":"「舍利弗！色空故無惱壞相，受空故無受相，想空故無知相，行空故無作相，識空故無覺相。何以故？舍利弗！非色異空，非空異色。色即是空，空即是色。受、想、行、識亦如是。"},{"p":"01-大正藏/09經集部類/T0604《佛說禪行三十七品經》.md","l":14,"id":"T0604","t":"佛說禪行三十七品經","x":"聞如是，一時佛遊於舍衛國祇樹給孤獨園。佛言：「諸比丘！若能彈指間，惟行自身身止觀，外身身止觀，內外身身止觀，分別念解世間癡惱，是為精進，為如佛教，非是愚癡食人施，何況能多行者，撮取其要；若彈指間，止觀痛，若止觀意及止觀法，內外分別念，解世間癡惱，皆如上說，何況多行者；是故可念行四意止。」"},{"p":"01-大正藏/07涅槃部類/T0386《蓮華面經》.md","l":18,"id":"T0386","t":"蓮華面經","x":"阿難言：「唯然！受如來教。」即隨佛行。未入彼城有跋提河。佛告阿難：「我今疲極，可入河浴。」爾時世尊脫欝多羅僧，置河岸上入河澡洗。"},{"p":"01-大正藏/07涅槃部類/T0388《大雲無想經卷第九》.md","l":18,"id":"T0388","t":"大雲無想經卷第九","x":"「善男子！是直道梵志，於大眾中，驚舉手言：『沙門瞿曇，作虛妄語。』是言即虛。善男子！一切法虛，如來能說，是故，如來不為妄語。一切諸法，無性、無定、無體、無緣，不可定說，空無出滅，不名為物，無淨不淨，如夢如幻，如水中月，如熱時炎，如𠯋聲嚮，如乾闥婆城、龜毛、兔角；貪瞋癡體，無有真實，因惡覺觀，而便出生。本無今有，以有還無。善男子！一切眾生，不知是相，是故唱言：『沙門瞿曇，作二種語，虛妄而說。』"},{"p":"01-大正藏/09經集部類/T0541《佛說佛大僧大經》.md","l":18,"id":"T0541","t":"佛說佛大僧大經","x":"親被疾著床，即呼長子，涕泣誡之：「夫生有死，萬物無常，持戒者安，犯戒者危，其持佛戒，終始無患。僧大尚小，仁孝清白……」厲已累爾，辭句適竟，奄忽歿故。"},{"p":"01-大正藏/04法華部類/T1917《六妙法門》.md","l":14,"id":"T1917","t":"六妙法門","x":"「六妙門」者，蓋是內行之根本，三乘得道之要逕。故釋迦初詣道樹，跏趺坐草，內思安般：一、數，二、隨，三、止，四、觀，五、還，六、淨，因此萬行開發，降魔成道。當知佛為物軌，示跡若斯，三乘正士豈不同遊此路？"},{"p":"01-大正藏/01阿含部類/T0045《大正句王經》.md","l":22,"id":"T0045","t":"大正句王經","x":"時正句王嚴整車駕出於宮城，與婆羅門及長者眾同共往詣尸利沙林鹿野之園。王心憍慢，所乘車駕至不通處，方乃下車徒步而進，行至園中尊者住處。時正句王與婆羅門長者眾，等見於尊者童子迦葉，初未信重不甚恭肅。王與尊者互伸問訊退坐一面，時婆羅門長者眾等，見王如是亦微鄭重，咸共相與圍繞而住。"},{"p":"01-大正藏/02本緣部類/T0186《普曜經》.md","l":20,"id":"T0186","t":"普曜經","x":"其名曰：慈氏菩薩，總豪王菩薩，師子英菩薩，吉義意菩薩，寂意行菩薩，分別辯才菩薩，逮無畏菩薩，進寂菩薩，大哀菩薩，如是上首菩薩三萬二千。"},{"p":"01-大正藏/01阿含部類/T0060《瞿曇彌記果經》.md","l":24,"id":"T0060","t":"瞿曇彌記果經","x":"彼時大女人瞿曇彌，不洗足，身有塵土，身瞪懵，啼泣在門前立。尊者阿難，遙見大女人瞿曇彌不洗足，身有塵土，身瞪懵，啼泣門前立，見已作是言：「何以故，瞿曇彌！不洗其足，身有塵土，身瞪懵，啼泣在門前立？」「如是。唯，尊者阿難！女人不得於此法律，不得信樂出家、棄家學道。」"},{"p":"01-大正藏/02本緣部類/T0169《月明菩薩經》.md","l":20,"id":"T0169","t":"月明菩薩經","x":"「復次，月明童男！菩薩大士在家、若出家，常樂經法施，常以善權迎逆人，意無貪心，正立法中住，奉守禁戒當如法。復有一事，月明童男！若比丘疾病窮厄，勤苦當憂，令得安隱給與醫藥；何但醫藥？尚當不惜肌肉，當供養之趣令得愈。"},{"p":"01-大正藏/16淨土宗部類/T0363《佛說大乘無量壽莊嚴經》.md","l":49,"id":"T0363","t":"佛說大乘無量壽莊嚴經","x":"「爾時，作法苾芻聞佛聖旨；偏袒右肩，右膝著地，合掌向佛即為宣說：『世尊！我發誓言：願如世尊證得阿耨多羅三藐三菩提；所居佛剎，具足無量不可思議功德莊嚴。所有一切眾生，及焰摩羅界，三惡道中地獄、餓鬼、畜生，皆生我剎受我法化，不久悉成阿耨多羅三藐三菩提，一切皆得身真金色。"},{"p":"01-大正藏/01阿含部類/T0043《閻羅王五天使者經》.md","l":22,"id":"T0043","t":"閻羅王五天使者經","x":"「閻王復問曰：『子為人時，豈不見世間男女婦人疾病者，軀體苦痛坐起不安，命近憂促，眾醫不能復治？』人言：『有是。』王曰：『汝謂可得不病耶？人生既老，法皆當病，曼身強健當勉為善，奉行經戒端身口意，奈何自放恣？』人言：『愚闇故耳。』王曰：『汝自以愚癡作惡，非父母君天、沙門道人過也、罪自由汝，豈得以不樂故止乎？今當受之。』是為閻王正教現第三天使。"},{"p":"01-大正藏/02本緣部類/T0187《方廣大莊嚴經》.md","l":37,"id":"T0187","t":"方廣大莊嚴經","x":"如來爾時哀愍諸天默然受請。是時諸天蒙佛垂許，歡喜踊躍生清淨心，稽首作禮右遶三匝，散天曼陀羅花，供養於佛忽然不現。"},{"p":"01-大正藏/02本緣部類/T0184《修行本起經》.md","l":24,"id":"T0184","t":"修行本起經","x":"於是目揵連，即從座起，前整衣服，長跪叉手，白佛言：「唯然世尊！今當承佛威神，持佛神力，為一切故，當廣說之。」"},{"p":"01-大正藏/04法華部類/T0274《佛說濟諸方等學經》.md","l":20,"id":"T0274","t":"佛說濟諸方等學經","x":"此大千界淨居身天，威靈尊勢大神妙天王、諸龍王、鬼神王、阿須倫王、迦留羅王、真陀羅王、摩睺勒王，各與無數億百千官屬往詣佛所，稽首足下，却住一面，叉手自歸。"},{"p":"01-大正藏/09經集部類/T0737《所欲致患經》.md","l":22,"id":"T0737","t":"所欲致患經","x":"時諸比丘分衛已竟，飯食畢訖，更整衣服，往詣佛所。稽首足下，却坐一面，前白世尊，說諸異道所可難問，悉次第說。"},{"p":"01-大正藏/01阿含部類/T0013《長阿含十報法經》.md","l":16,"id":"T0013","t":"長阿含十報法經","x":"佛在舍衛國祇樹給孤獨園。是時，賢者舍利曰：「請諸比丘聽說法，上亦好、中亦好、竟亦好，有慧、有巧、最具淨除至竟說行，聽從一增至十法，聽向意著意，聽說如言。」諸比丘從賢者舍利曰：「請願欲聞。」舍利曰：「便說從一增起至十法，皆聚成無為。從苦得要出，一切惱滅。"},{"p":"01-大正藏/05華嚴部類/T0302《度諸佛境界智光嚴經》.md","l":20,"id":"T0302","t":"度諸佛境界智光嚴經","x":"及與萬比丘尼：摩訶波闍波提比丘尼、耶輸陀羅比丘尼——等入一切善神清白之法，近一切智入一切智明，善達諸法無性，入諸法無性，入諸法無相，得諸法實際，知諸法不生，一切安立不思議解脫之定，教化眾生，不作意不思惟，而能現身四種威儀。"},{"p":"01-大正藏/18史傳部類/T2038《釋鑑稽古略續集》.md","l":36,"id":"T2038","t":"釋鑑稽古略續集","x":"自太祖成吉思皇帝。於宋寧宗開禧二年丙寅歲。法天啟運。稱聖武年號。建大蒙古國號。都和林云上都。至理宗紹定二年己丑。太宗嗣位。至淳祐六年丙午定宗嗣位。至淳祐十一年辛亥。憲宗嗣位。至開慶元年己未。慶宗嗣位。至景定元年庚申歲。世祖登基稱中統。至甲子改元至元。歷六世五十九年。今從世祖甲子元年敘起。"},{"p":"01-大正藏/03般若部類/T0228《佛說佛母出生三法藏般若波羅蜜多經》.md","l":22,"id":"T0228","t":"佛說佛母出生三法藏般若波羅蜜多經","x":"是時，尊者舍利子即起是念：「今尊者須菩提，為以自智慧辯才而為宣說菩薩摩訶薩般若波羅蜜多耶？為以佛威神及加持力而為說耶？」"},{"p":"01-大正藏/03般若部類/T0254《般若波羅蜜多心經》.md","l":18,"id":"T0254","t":"般若波羅蜜多心經","x":"即時具壽舍利子，承佛威神，合掌恭敬，白觀世音自在菩薩摩訶薩言：「聖者！若有欲學甚深般若波羅蜜多行，云何修行？」如是問已。"},{"p":"01-大正藏/02本緣部類/T0179《銀色女經》.md","l":29,"id":"T0179","t":"銀色女經","x":"「彼銀色女有所須故，從自家出往至他舍。入他舍已，見彼家內新產婦女生一童子，端正殊妙，身色成就。時產婦女以手擎子而欲食之。時銀色女即問之曰：『妹何所作？』"},{"p":"01-大正藏/01阿含部類/T0024《起世經》.md","l":22,"id":"T0024","t":"起世經","x":"時，諸比丘同白佛言：「大德世尊！我等比丘，於此法堂，食後共集。大眾詳議作如是言：『是諸長老，未曾有也。云何世間如是成立？云何世間如是散壞？云何世間壞已復立？云何世間立已安住？』大德世尊！我等向來集坐言論，正議斯事。」"},{"p":"01-大正藏/05華嚴部類/T0306《大方廣佛花嚴經修慈分》.md","l":26,"id":"T0306","t":"大方廣佛花嚴經修慈分","x":"「佛子！若有眾生為求菩提，而修諸行願常安樂者，應修慈心以自調伏。如是修習，於念念中，常具修行六波羅蜜，速能逮及諸忍之地，速得圓滿無上正覺，具足十力、四無所畏、十八不共法、三十二相、八十種好，最上功德莊嚴其身；盡於未來，常住安樂；亦能除滅一切眾生無始已來諸業重障。"},{"p":"01-大正藏/16淨土宗部類/T1962《五方便念佛門》.md","l":16,"id":"T1962","t":"五方便念佛門","x":"凡住心一境，名曰凝心。且如行者，念佛之時諦觀如來玉毫金相，凝然寂靜了亮洞徹，名凝心禪。"},{"p":"01-大正藏/18史傳部類/T2065《海東高僧傳》.md","l":41,"id":"T2065","t":"海東高僧傳","x":"贊曰。火炎崑岡。玉石俱焚。霜嚴草野。蕭蘭共悴。師之艱難險阻。誠曰殆哉。雖伐樹削跡不足比也。然隨時隱現。若青山白雲之開遮。遇害虧盈。如碧潭明月之橯樚。捐軀濟溺。道之以興。菩薩法護。正當如此。其適來桑域。決膜生盲。亦乘夙願而至者耶。"},{"p":"01-大正藏/03般若部類/T0253《般若波羅蜜多心經》.md","l":28,"id":"T0253","t":"般若波羅蜜多心經","x":"即時，世尊從廣大甚深三摩地起，讚觀自在菩薩摩訶薩言：「善哉，善哉！善男子！如是，如是！如汝所說。甚深般若波羅蜜多行，應如是行。如是行時，一切如來皆悉隨喜。」"},{"p":"01-大正藏/06寶積部類/T0310《大寶積經》.md","l":16,"id":"T0310","t":"大寶積經","x":"叡聖重光，文思御曆，吞沙靜㜸，練石稱神，巢燧執鞭，羲農擁篲。懸法王之鏡，轉梵帝之輪，被正朔於蟠桃，混車書於細柳。三藏沙門菩提流志者，南天竺國淨行婆羅門種，姓迦葉氏也。年十有二，外道出家，事波羅奢羅，學聲明僧佉等論，并曆數呪術及陰陽等，年踰耳順遽乃心歸。知外法之乖違，悟釋教之深妙，隱居名岳積習頭陀，初就耶舍瞿沙三藏學經論，其後遍遊五天竺國。"},{"p":"01-大正藏/10密教部類/T1011《佛說無量門微密持經》.md","l":109,"id":"T1011","t":"佛說無量門微密持經","x":"賢者舍利弗白佛言：「當何名此經？」佛言：「是法之要，名無量門微密之持，一名成道降魔得一切智，當奉持之。」佛說是已，皆歡喜受。"},{"p":"01-大正藏/01阿含部類/T0063《解夏經》.md","l":26,"id":"T0063","t":"解夏經","x":"時舍利弗聞佛忍可，投誠禮謝。復白佛言：「世尊！如佛為我忍可三業，於此會中五百苾芻，身口意業所有不善，唯願世尊，亦如是忍。」"},{"p":"01-大正藏/01阿含部類/T0005《佛般泥洹經》.md","l":18,"id":"T0005","t":"佛般泥洹經","x":"公受王教，即嚴車五百，乘騎二千，步人二千，往到王舍國，得步徑止車下，到佛所見佛前。頭面著佛足，佛與机使坐，問國丞相：「從何所來？」公言：「王使臣來，𥡳首佛足，問佛消息，身體平安不？飡食如常不？」佛即問：「王及國人民，寧安和不？穀糴平賤不？」公言：「得佛恩，皆自安和，風雨時節，國中豐熟。」佛言：「公行道人馬，皆平安不？」公言：「得佛恩，行道皆平安無他。」"},{"p":"01-大正藏/18史傳部類/T2040《釋迦譜》.md","l":122,"id":"T2040","t":"釋迦譜","x":"由此本緣名剎利種(樓炭云以是因緣從昔至今。起剎利種。中阿含經云。地主者謂剎利)。"},{"p":"01-大正藏/01阿含部類/T0028《園生樹經》.md","l":22,"id":"T0028","t":"園生樹經","x":"「復次彼樹生俱砧摩羅迦時，即如聲聞人離諸喜愛，身得輕安適悅妙樂，獲得第三禪離喜妙樂定。"},{"p":"01-大正藏/04法華部類/T1520《妙法蓮華經論優波提舍》.md","l":28,"id":"T1520","t":"妙法蓮華經論優波提舍","x":"威儀如法住成就者，有四種示現。何等為四？一者四眾圍繞；二者前後；三者供養恭敬；四者尊重讚歎。如經「爾時世尊四眾圍繞，供養恭敬尊重讚歎」故。"},{"p":"01-大正藏/03般若部類/T0246《仁王護國般若波羅蜜多經》.md","l":34,"id":"T0246","t":"仁王護國般若波羅蜜多經","x":"時室羅筏國波斯匿王作是思惟：「今佛現是希有之相，必雨法雨，普皆利樂。」即問寶蓋、無垢稱等諸優婆塞，舍利弗、須菩提等諸大聲聞，彌勒、師子吼等諸菩薩摩訶薩言：「如來所現，是何瑞相？」時諸大眾無能答者。波斯匿王等，承佛神力廣作音樂，欲、色諸天各奏無量天諸伎樂，聲遍三千大千世界。"},{"p":"01-大正藏/16淨土宗部類/T0310《大寶積經》無量壽如來會.md","l":37,"id":"T0310","t":"大寶積經","x":"「阿難！彼佛法中有一比丘名曰法處，有殊勝行願及念慧力增上，其心堅固不動，福智殊勝人相端嚴。阿難！彼法處比丘往詣世間自在王如來所，偏袒右肩頂禮佛足，向佛合掌以頌讚曰："},{"p":"01-大正藏/03般若部類/T0245《佛說仁王般若波羅蜜經》.md","l":32,"id":"T0245","t":"佛說仁王般若波羅蜜經","x":"白佛言：「若諸法爾者，菩薩護化眾生，為化眾生耶？」「大王！法性色受想行識常樂我淨，不住色，不住非色，不住非非色，乃至受想行識亦不住非非住。何以故？非色如，非非色如。世諦故、三假故，名見眾生，一切生性實故，乃至諸佛、三乘、七賢、八聖亦名見，六十二見亦名見。大王！若以名名見一切法，乃至諸佛三乘四生者，非非見一切法也。」"},{"p":"01-大正藏/17禪宗部類/T1985《鎮州臨濟慧照禪師語錄》.md","l":16,"id":"T1985","t":"鎮州臨濟慧照禪師語錄","x":"薄伽梵「正法眼藏涅槃妙心」付摩訶迦葉，是為第一祖。逮二十八祖菩提達磨提十方三世諸佛密印而來震旦，是時中國始知佛法有教外別傳、不立文字、直指人心、見性成佛。厥後優鉢羅花於時出現，芬芳馥郁，一華五葉，香風匝地、寶色照天，各放無量光明，輝映大千世界。"},{"p":"01-大正藏/01阿含部類/T0062《新歲經》.md","l":30,"id":"T0062","t":"新歲經","x":"彼時世尊，告賢者阿難：「汝往擊于揵搥，時今已到。」阿難受教，即從座起，而撾揵搥，聲遍佛土，一佛大國，地獄、餓鬼、畜生，聞揵搥音，承佛威神，一切諸病苦毒悉除，皆得安隱。"},{"p":"01-大正藏/17禪宗部類/T2004《萬松老人評唱天童覺和尚頌古從容庵錄》.md","l":160,"id":"T2004","t":"萬松老人評唱天童覺和尚頌古從容庵錄","x":"示眾云。閉門打睡接上上機。顧鑑頻申。曲為中下。那堪上曲䚄木弄鬼眼睛。有箇傍不肯底。出來。也怪伊不得。"},{"p":"01-大正藏/09經集部類/T0702《佛說施燈功德經》.md","l":24,"id":"T0702","t":"佛說施燈功德經","x":"「舍利弗！如此福德非是一切聲聞、緣覺所能了知，唯佛、如來乃能知也！舍利弗！求世報者，福德尚爾，何況以清淨深樂心、不求果報安住恭敬、相續無間念佛功德善男子、善女人等所生福德？舍利弗！照道一階福德尚爾，何況全照一階道也——或二階道、或三階道、或四階道——或及塔身一級、二級乃至多級；一面、二面乃至四面及佛形像？"},{"p":"01-大正藏/18史傳部類/T2036《佛祖歷代通載》.md","l":62,"id":"T2036","t":"佛祖歷代通載","x":"一教門事要。異同訛正略加考定。據諸傳記摭集。不以私臆謬加論辨。或恐繁失於冗簡失於陋。以俟博雅之士。改而正之。"},{"p":"01-大正藏/09經集部類/T0528《佛說菩薩逝經》.md","l":18,"id":"T0528","t":"佛說菩薩逝經","x":"佛到檀尼加柰家求食。時，逝在內第三門中住。遙見佛來歡喜，逝即心念言：「是人何以端正無比好乃爾？好如明月珠，光明如日月，其色如黃金，好如月十五日盛滿。」"},{"p":"01-大正藏/09經集部類/T0554《佛說奈女耆婆經》.md","l":14,"id":"T0554","t":"佛說奈女耆婆經","x":"佛在世時，維耶離國王苑中，自然生一奈樹，枝葉繁茂，實又加大，既有光色，香美非凡。王實愛此奈，自非宮中尊貴美人，不得噉此奈果。"},{"p":"01-大正藏/06寶積部類/T0320《父子合集經》.md","l":24,"id":"T0320","t":"父子合集經","x":"佛言：「憍陳如！汝居聲聞最為上首，先解諦義，有大名稱，一切眾生尊奉如師。且止是說，不須汝往。」"},{"p":"01-大正藏/09經集部類/T0564《佛說轉女身經》.md","l":20,"id":"T0564","t":"佛說轉女身經","x":"佛言：「阿泥盧豆！我先明見此女在胎而不說之。所以者何？若有眾生不信如來誠諦之言，此人長夜受大苦惱！」"},{"p":"01-大正藏/16淨土宗部類/T1762《阿彌陀經要解》.md","l":26,"id":"T1762","t":"阿彌陀經要解","x":"第五教相者，此是大乘菩薩藏攝，又是無問自說，徹底大慈之所加持，能令末法多障有情依斯徑登不退。故雖經法滅盡之後，仍以悲心弘願特留此經住世百年，廣度含識。譬如阿伽陀藥萬病總持，絕待圓融不可思議。《華嚴》之奧藏、《法華》之祕髓，一切諸佛之心要、菩薩萬行之司南，皆不出於此矣。設欲廣為歎述，窮劫莫盡，有智者自當知之。"},{"p":"01-大正藏/04法華部類/T1912《止觀輔行傳弘決》.md","l":16,"id":"T1912","t":"止觀輔行傳弘決","x":"(濟行之教有宗，信教堪輔行；顯教之行符理，驗行可傳弘。行何所弘？非眾教不立。教何所輔？非妙行莫詮。乃漸以三聞全教行一轍，若咨稟口決、若審理要決、若設徵決疑、若取類決擇、若引廣決略、若攝廣決正、若決疏文勢、若決通觀道、若案文判失、若准部斷謬。攬斯眾旨輒為首題，聊申所傳不遺先見)。"},{"p":"01-大正藏/08大集部類/T0399《寶女所問經》.md","l":22,"id":"T0399","t":"寶女所問經","x":"其名曰：明天菩薩、選遊步菩薩、擇戰鬪菩薩、照明藏菩薩、蠲慢意菩薩、踊步菩薩、眼觀菩薩、雷音菩薩、離冥菩薩，如是等類諸菩薩眾，不可限量無邊無際不可引喻。"},{"p":"01-大正藏/04法華部類/T0266《佛說阿惟越致遮經》.md","l":20,"id":"T0266","t":"佛說阿惟越致遮經","x":"於是賢者舍利弗後夜寤起，自出其室，發心往詣文殊師利。欲入其室，未入之頃，見佛神室則前進矣。覩十万蓮華不可稱計圍繞佛屋，又復遙聞大音樂聲若干種響。其大蓮華自然衍光，遍照祇樹，悉周舍衛靡不見焉，三千大千佛之境界光耀巍巍。"},{"p":"01-大正藏/03般若部類/T1711《般若波羅蜜多心經贊》.md","l":24,"id":"T1711","t":"般若波羅蜜多心經贊","x":"言題目者，「佛說」即是標能說主，梵音佛陀，此翻名覺，具真、俗智，自、他覺滿，故名為佛。開敷妙門，令眾生解，名之為說。「般若波羅蜜多」，辨所說法，此土翻為智到彼岸。「心經」正顯能詮之教，盧道之中，心王獨秀，於諸般若，此教最尊，從諭立名，故曰心也。經有二義，貫穿、攝持，貫穿所應說義，攝持所化生故，此即依主，就能、所詮，法、諭立號，故言「佛說般若波羅蜜多心經」。"},{"p":"01-大正藏/16淨土宗部類/T1756《阿彌陀經義述》.md","l":18,"id":"T1756","t":"阿彌陀經義述","x":"佛說阿彌陀經者，乃勸生淨土不退菩提者也。皎三明以像秋月，振四辨而類春雷，讚淨境以示西方，美勝因而指東土，班自我口，暢之彼心，以覺合機，故稱佛說。阿彌陀，此云無量壽，光明、說法、徒眾皆悉無量，為引物情，偏標壽名，故名無量。經有二義，訓經、訓常，眾聖所遊，曰經古經今，恒定曰常，故名佛說阿彌陀經。"},{"p":"01-大正藏/09經集部類/T0546《佛說金耀童子經》.md","l":22,"id":"T0546","t":"佛說金耀童子經","x":"婆羅門言：「瞿曇！我今現世亦有福德，於其家中生一童子，金色光輝，容儀相好，可似瞿曇，得未曾有。"},{"p":"01-大正藏/04法華部類/T1722《法華遊意》.md","l":26,"id":"T1722","t":"法華遊意","x":"佛何因緣故說是《妙法花經》耶？諸佛不以無事及少因緣而自發言，今有何等大因緣故說是經耶？"},{"p":"01-大正藏/09經集部類/T0475《維摩詰所說經》.md","l":65,"id":"T0475","t":"維摩詰所說經","x":"佛言：「善哉！寶積！乃能為諸菩薩，問於如來淨土之行。諦聽，諦聽！善思念之，當為汝說！」於是寶積及五百長者子受教而聽。"},{"p":"01-大正藏/09經集部類/T0752《佛說五無返復經》.md","l":24,"id":"T0752","t":"佛說五無返復經","x":"梵志自念：「此人無返復，兒死在地，情不愁憂，而返索食。此人不慈，無有比類。」梵志便行入城，詣耕者家，見死兒母，即便語之：「卿兒已死，父言：『但持一人食來。』何以不念子耶？」"},{"p":"01-大正藏/09經集部類/T0804《佛說解憂經》.md","l":66,"id":"T0804","t":"佛說解憂經","x":"佛言：「苾芻！如是補特伽羅輪迴眾生以骨作聚，如妙高山，不壞不爛。如是無學聲聞，證四聖諦，了知此苦，真實為苦、苦滅，證苦聖諦。彼補特伽羅見此屍骨不知是苦，亦不能滅三界煩惱。若滅三界煩惱，證須陀洹不空法，決定得菩提。由於七生天、人之中，作斷輪迴，除滅煩惱。七生滿已，聖諦現前，正見智慧，滅盡餘惑，到涅槃寂靜，彼補特伽羅方得解脫輪迴之苦！」"},{"p":"01-大正藏/09經集部類/T0427《佛說八吉祥神呪經》.md","l":22,"id":"T0427","t":"佛說八吉祥神呪經","x":"「去是二恒沙，有佛名紺琉璃具足王如來、無所著、最正覺，今現在說法，其世界名曰慈哀光明。"},{"p":"01-大正藏/09經集部類/T0760《惟日雜難經》.md","l":26,"id":"T0760","t":"惟日雜難經","x":"菩薩精進行二十劫可得佛。用有三意故不得佛。何等為三？有佛意、有辟支佛意、有阿羅漢意，用是三意故不得佛。要為隨多得之意，在佛多得佛、在辟支佛多得辟支佛、在阿羅漢多得阿羅漢，如秤隨重者得之。"},{"p":"01-大正藏/04法華部類/T1916《釋禪波羅蜜次第法門》.md","l":91,"id":"T1916","t":"釋禪波羅蜜次第法門","x":"(天台山修禪寺顗禪師於都講說禪法，大莊嚴寺沙門法慎記。預聽學輒依說採記。法門深廣，難可委悉，若取具足，有三十卷，今略出前卷要用，流通此本，於天台更得治改前諸同學所寫之者。爾時既未好成就，猶應闕略，或繁而不次，若見此本，更改定之，庶於學者得免謬失矣)。"},{"p":"01-大正藏/07涅槃部類/T0376《佛說大般泥洹經》.md","l":34,"id":"T0376","t":"佛說大般泥洹經","x":"復有閻浮提內大長者五恒河沙，深樂正法淳修戒行眾德成就，伏諸異學及亂法者，深樂大乘。其名日：月光王薝蔔華首長者，法首長者，如是等長者子及長者女五恒河沙，於晨朝時承佛威神，辦眾供具倍復勝前，來詣佛所稽首請佛，頭面禮足於一面住。"},{"p":"01-大正藏/09經集部類/T0776《佛說四品法門經》.md","l":20,"id":"T0776","t":"佛說四品法門經","x":"尊者阿難思惟如是事已，從座而起，往詣佛所。到佛所已，頭面禮足，修奉已畢，住立一面，而白佛言：「世尊！我獨靜室，心生是念：『世間所有驚怖等事，皆是愚人所有；智者即無。』惟願世尊，為我解說。」"},{"p":"01-大正藏/10密教部類/T1002《不空羂索毘盧遮那佛大灌頂光真言》.md","l":20,"id":"T1002","t":"不空羂索毘盧遮那佛大灌頂光真言","x":"又法以新米𡅄羅，澡浴清淨著淨衣服已，以藥和水研，加持一百八遍點米𡅄羅眼中，奮怒加持一千八十遍，則便起坐，所問皆答。欲放者，加持白芥子水二十一遍，散米𡅄羅上，即便如舊。若為貴人相請喚者，以藥點眼當往見之，則相賓敬。"},{"p":"01-大正藏/01阿含部類/T0080《佛為首迦長者說業報差別經》.md","l":54,"id":"T0080","t":"佛為首迦長者說業報差別經","x":"「或有業能令眾生生於惡道，形容殊妙，眼目端嚴，膚體光澤，人所樂見；或有業能令眾生生於惡道，形容醜陋，膚體麁澁，人不喜見；或有業能令眾生生於惡道，身口臭穢，諸根殘缺。"},{"p":"01-大正藏/10密教部類/T0848《大毘盧遮那成佛神變加持經》.md","l":82,"id":"T0848","t":"大毘盧遮那成佛神變加持經","x":"「祕密主！彼揀擇地，除去礫石碎瓦破器、髑髏毛髮、糠糟灰炭、刺骨朽木等，及蟲蟻蜣蜋毒螫之類，離如是諸過。遇良日晨、定日、時分、宿直、諸執皆悉相應，於食前時值吉祥相，先當為一切如來作禮，以如是偈警發地神："},{"p":"01-大正藏/09經集部類/T0574《佛說堅固女經》.md","l":20,"id":"T0574","t":"佛說堅固女經","x":"佛說是語時，眾中有一優婆夷，名曰堅固，即從坐起整理衣服，合十指掌而白佛言：「世尊！我今為欲利益一切眾生故，為欲施一切眾生安樂故，為欲憐愍一切世界眾生故，為欲度脫一切天人故，發阿耨多羅三藐三菩提心。"},{"p":"01-大正藏/02本緣部類/T0153《菩薩本緣經》.md","l":25,"id":"T0153","t":"菩薩本緣經","x":"過去有王，名地自在，受性暴惡，好行征伐。時，有小國八萬諸王，首戴寶冠常來朝侍；其王口惡，身行無善，常為非法侵陵他境。王有輔相——大婆羅門，修清淨行，智人所讚，口言柔軟，不宣麤惡，有所造作，能速成辦，面目端嚴，為世所敬，四毘陀典靡不綜練；諸婆羅門所有經論，通達解了無有遺餘。"},{"p":"01-大正藏/17禪宗部類/T1993《黃龍慧南禪師語錄》.md","l":20,"id":"T1993","t":"黃龍慧南禪師語錄","x":"歲旦上堂。僧問。不求諸聖。不重己靈。未是衲僧分上事。如何是衲僧分上事。師云。三十年來。罕逢此問。進云。恁麼則辜負諸聖去也。師云。話也未答。何言辜負。僧撫掌一下。師云。吽。放過即不可。"},{"p":"01-大正藏/03般若部類/T2734《金剛暎卷上》.md","l":26,"id":"T2734","t":"金剛暎卷上","x":"依無著十八住八住處三地仍橫三問多是定位文隱或重天親堅答三問亦名單答三問天親文顯顯答仍斷疑。"},{"p":"01-大正藏/08大集部類/T0414《菩薩念佛三昧經》.md","l":22,"id":"T0414","t":"菩薩念佛三昧經","x":"時栴檀天子默然生念：「過去諸佛皆為諸天、世人、沙門、婆羅門演諸佛所說菩薩念佛三昧。」復作是念：「今我世尊亦應如昔過去諸佛，安樂世間諸人天故，宣說菩薩念佛三昧。」"},{"p":"01-大正藏/01阿含部類/T0010《白衣金幢二婆羅門緣起經》.md","l":30,"id":"T0010","t":"白衣金幢二婆羅門緣起經","x":"白衣、金幢二婆羅門，俱白佛言：「世尊！諸婆羅門，於三明中，云何得無輕毀凌辱及諸譏謗？而婆羅門，三明典中，作如是言：『諸婆羅門，如是清淨，是真婆羅門，是梵王子，清淨口生，梵王種類，梵王所化，梵王所授。是故，諸婆羅門，如是清淨，是真婆羅門。』世尊！而我白衣、金幢，亦以眷屬所纏，不得解脫，減失善法，增長惡法。世尊！此亦是為我婆羅門三明典中輕毀凌辱譏謗等事。」"},{"p":"01-大正藏/16淨土宗部類/T0361《佛說無量清淨平等覺經》.md","l":18,"id":"T0361","t":"佛說無量清淨平等覺經","x":"其女弟子，名曰：大欽姓比丘尼、幻者比丘尼、蓮華色比丘尼、生地動比丘尼、生地擔比丘尼、生則侍者頭痛比丘尼、安豐殖比丘尼、體柔軟比丘尼、勇生行比丘尼、自淨比丘尼。"},{"p":"01-大正藏/16淨土宗部類/T1964《西方要決釋疑通規》.md","l":14,"id":"T1964","t":"西方要決釋疑通規","x":"仰惟釋迦啟運弘益有緣，教闡隨方並霑法潤，親逢聖化道悟三乘，福薄因疎勸歸淨土。作斯業者，專念彌陀，一切善根迴生彼國；彌陀本願，誓度娑婆，上盡現生一形、下至臨終十念，俱能決定，皆得往生。當今學者特懷疑慮，為諸經論文有相違，若不會通疑端莫絕。略陳十四，種釋湍流，博識通才幸尋取悟耳。"},{"p":"01-大正藏/06寶積部類/T0340《文殊師利所說不思議佛境界經》.md","l":22,"id":"T0340","t":"文殊師利所說不思議佛境界經","x":"文殊師利菩薩言：「世尊！佛境界者，非眼境界、非色境界、非耳境界、非聲境界、非鼻境界、非香境界、非舌境界、非味境界、非身境界、非觸境界、非意境界、非法境界，無如是等差別境界，是乃名為諸佛境界。世尊！善男子善女人有欲入於佛境界者，以無所入而為方便乃能悟入。」"},{"p":"01-大正藏/05華嚴部類/T0304《大方廣入如來智德不思議經》.md","l":18,"id":"T0304","t":"大方廣入如來智德不思議經","x":"與大比丘眾六十二億人俱，皆悉了達諸法實相，自性平等，猶如虛空，無所依著，永離一切煩惱蓋纏。一切如來智慧方便皆能隨入，於一法中了一切法，無分別智常現在前，常勤修習趣種智道，心無退轉，皆已成就到彼岸智，隨一切境，所行方便，無不具足。"},{"p":"01-大正藏/07涅槃部類/T0385《中陰經》.md","l":22,"id":"T0385","t":"中陰經","x":"當生之時，天地六反震動，十方諸佛皆來扶助，是謂一弘誓法。云何為六反震動？東踊西沒、西踊東沒、北踊南沒、南踊北沒、四面都踊則中央沒、中央踊則四面沒。"},{"p":"01-大正藏/10密教部類/T1044《佛說六字呪王經》.md","l":24,"id":"T1044","t":"佛說六字呪王經","x":"「若為某甲作惡呪詛，若作已若當作。若天、若龍、若夜叉、若羅剎，及與一切能作惡呪詛者，悉皆滅之。若佉歐陀羅、若毘陀羅、若富多那所為，悉皆滅之。眾惡都盡，眾善補處，願此呪常吉。以此真實章句，使某甲晝安夜安晝夜常安，得壽百歲得見百秋。何以故？世間上法無過佛法，人天所敬、眾鬼奉受，離欲無著。」即說呪曰："},{"p":"01-大正藏/09經集部類/T0678《相續解脫地波羅蜜了義經》.md","l":30,"id":"T0678","t":"相續解脫地波羅蜜了義經","x":"觀世音白佛言：「奇哉世尊！無上菩提大利大果，彼諸菩薩破大癡網度大罪過，得無上菩提。」"},{"p":"01-大正藏/04法華部類/T1519《妙法蓮華經憂波提舍》.md","l":28,"id":"T1519","t":"妙法蓮華經憂波提舍","x":"釋曰：此經法門初第一品，示現七種功德成就，此義應知。何等為七？一者序分成就；二者眾成就；三者如來欲說法時至成就；四者依所說法威儀隨順住成就；五者依止說因成就；六者大眾現前欲聞法成就；七者文殊師利菩薩答成就。"},{"p":"01-大正藏/01阿含部類/T0020《佛開解梵志阿颰經》.md","l":24,"id":"T0020","t":"佛開解梵志阿颰經","x":"阿颰言：「我聞天帝釋，與第七梵，皆下事之，所教弟子，悉得五通，輕舉能飛，達視洞聽，知人意志，及生所從來，死所趣向。此蓋天師，何肯來謁！」"},{"p":"01-大正藏/08大集部類/T0421《奮迅王問經》.md","l":14,"id":"T0421","t":"奮迅王問經","x":"魏尚書令儀同高公今欲以此四種奮迅於一切處普奮迅故，置能譯人在宅上面出此四種奮迅法門。"},{"p":"01-大正藏/10密教部類/T0936《大乘無量壽經》.md","l":62,"id":"T0936","t":"大乘無量壽經","x":"「若有自書寫、教人書寫是無量壽宗要經，受持讀誦，畢竟不墮地獄，在在所生得宿命智。陀羅尼曰："},{"p":"01-大正藏/09經集部類/T0596《佛說天王太子辟羅經》.md","l":24,"id":"T0596","t":"佛說天王太子辟羅經","x":"「王後壽終，魂靈上生天上，作天妙王。天上壽盡，下生世間，位為飛行皇帝，安所出入，七寶飛行，導從前後。今復上天為天王太子。所以然者，自身持戒，覆濟眾生之所致也。奉佛教戒，正身心行，無不獲其福者矣。」"},{"p":"01-大正藏/01阿含部類/T0012《大集法門經》.md","l":22,"id":"T0012","t":"大集法門經","x":"是時，末利優婆塞，聞佛言已，即從座起，禮世尊足，合掌恭敬，普遍頂禮諸苾芻眾，繞佛三匝，出離佛會。"},{"p":"01-大正藏/03般若部類/T0241《金剛頂瑜伽理趣般若經》.md","l":20,"id":"T0241","t":"金剛頂瑜伽理趣般若經","x":"佛說如是菩薩句義般若理趣清淨法已，告金剛手菩薩等言：「金剛手菩薩！若有得聞此一切法自性清淨般若波羅蜜多理趣法門，一經於耳，所有煩惱障業極重諸罪皆自消滅，乃至菩提，不生惡道。若能日日受持讀誦正念思惟，即於此生定得一切法平等性金剛三摩地。經十六大菩薩生，定得如來執金剛性，疾證無上正等菩提。」"},{"p":"01-大正藏/17禪宗部類/T1992《汾陽無德禪師語錄》.md","l":20,"id":"T1992","t":"汾陽無德禪師語錄","x":"胡僧金錫光。為法到汾陽。六人成大器。勸請為敷揚。伸出西河爪距。抉破古今窠臼。義天無滓。心鏡無痕。圓如明月珠。快似金剛劍。一斬一切斬。一斷一切斷。上無攀仰。下絕己躬。常光現前。壁立萬仞。木石首座重行刊鏤。廣其流通。療狂子之多疑。救達人之少悟。"},{"p":"01-大正藏/02本緣部類/T0157《悲華經》.md","l":32,"id":"T0157","t":"悲華經","x":"「善男子！其佛世界有菩提樹名因陀羅，高三千由旬，樹莖縱廣五百由旬，枝葉縱廣一千由旬。下有蓮華，琉璃為莖高五百由旬。一一諸華各有一億百千金葉高五由旬，馬瑙為䩸、七寶為鬚高十由旬，縱廣正等滿七由旬。爾時，蓮華尊佛坐此華上，即於昨夜成阿耨多羅三藐三菩提。其菩提華座周匝復有種種蓮華，有諸菩薩各坐其上，見蓮華尊佛種種變化。」"},{"p":"01-大正藏/01阿含部類/T0049《求欲經》.md","l":18,"id":"T0049","t":"求欲經","x":"彼時，有異比丘從座起，一向著衣，叉手向尊者舍利弗，白尊者舍利弗曰：「云何，尊者舍利弗！何因何緣，此前二種人俱有求欲、俱有著意，說一人弊惡、說一人最勝耶？復何因何緣，此後二種人，俱有無求欲、俱有無著，說一人弊惡、說一人最勝耶？」"},{"p":"01-大正藏/17禪宗部類/T1999《密菴和尚語錄》.md","l":20,"id":"T1999","t":"密菴和尚語錄","x":"師於乾道三年八月初一日。就本院受請。陞座云。適來未鳴鼓已前。喚作傑上座。而今陞座已後。喚作烏巨長老。驟爾更其名易其號。披毛戴角。拕犁拽把。向異類中。頭出頭沒。既然業債難逃。只得歡喜忍受。恁麼見得徹去。新長老出世事畢。其或未然。傑上座今日失利。敘謝不錄。"},{"p":"01-大正藏/03般若部類/T0222《光讚經》.md","l":22,"id":"T0222","t":"光讚經","x":"於是世尊即時欣笑，從諸毛孔放眾光明，照此三千大千世界，普遍十方無不周接。江河沙等諸佛世界，其有群萌，為光所照悉皆寂然，存于無上正真之道。是時世尊則演如來清淨真妙志性光明，照此三千大千世界，普及十方各江河沙等諸佛國土，假令人民逮斯光者，則皆究竟至於無上正真之道。"},{"p":"01-大正藏/07涅槃部類/T1763《大般涅槃經集解》.md","l":42,"id":"T1763","t":"大般涅槃經集解","x":"案曇准曰：蓋是吉祥之靈府、生白之虛室也。撿因則行逾十地、覈果則妙極摳始，冥造弗能移、玄運莫之動，一寂孔神，此以常為宗也。然群美不可盡言，故偏寄三德：取其洞照虛明，目之般若；應不搖寂，字曰法身；結惑都亡，謂之解脫。三義既彰，涅槃稱在。大是梁方之言，涅槃是西域通語，彼訓多含，此方無以偏譯，故直存胡本以為題目。"},{"p":"01-大正藏/17禪宗部類/T2003《佛果圜悟禪師碧巖錄》.md","l":14,"id":"T2003","t":"佛果圜悟禪師碧巖錄","x":"自四十二章經入中國。始知有佛。自達磨至六祖傳衣。始有言句。曰本來無一物為南宗。曰時時勤拂拭為北宗。於是有禪宗頌古行世。其徒有翻案法。呵佛罵祖。無所不為。間有深得吾詩家活法者。然所謂第一義。焉用言句。雪竇圜悟。老婆心切。大慧已一炬丙之矣。嵎中張煒明遠。燃死灰復板行。亦所謂老婆心切者歟。大德四年庚子。四月初八日癸丑。紫陽山方回萬里序。"},{"p":"01-大正藏/01阿含部類/T0022《寂志果經》.md","l":22,"id":"T0022","t":"寂志果經","x":"王前詣佛，問訊占對却住一面——觀佛比丘眾，悉坐寂定，無量清淨，甚深微妙，其心欣然——叉手向佛，白世尊言：「佛心寂然，微妙無念，弟子亦爾。願令我心志于微妙隱定如是。」"},{"p":"01-大正藏/07涅槃部類/T0396《佛說法滅盡經》.md","l":18,"id":"T0396","t":"佛說法滅盡經","x":"無央數眾來詣佛所，稽首于地。世尊寂靜默無所說，光明不現。賢者阿難作禮白佛言：「世尊前後說法威光獨顯，今大眾會光更不現，何故如此？其必有故，願聞其意。」"},{"p":"01-大正藏/16淨土宗部類/T1524《無量壽經優波提舍》.md","l":71,"id":"T1524","t":"無量壽經優波提舍","x":"云何觀佛功德莊嚴成就？觀佛功德莊嚴成就者，有八種應知。何等八種？一者座莊嚴；二者身莊嚴；三者口莊嚴；四者心莊嚴；五者眾莊嚴；六者上首莊嚴；七者主莊嚴；八者不虛作住持莊嚴。"},{"p":"01-大正藏/16淨土宗部類/T0360《佛說無量壽經》.md","l":30,"id":"T0360","t":"佛說無量壽經","x":"尊者阿難承佛聖旨，即從座起，偏袒右肩，長跪合掌而白佛言：「今日世尊諸根悅豫，姿色清淨，光顏巍巍，如明鏡淨影暢表裏，威容顯耀超絕無量，未曾瞻覩殊妙如今。唯然，大聖！我心念言：『今日世尊住奇特法、今日世雄住佛所住、今日世眼住導師行、今日世英住最勝道、今日天尊行如來德。去來現在佛佛相念，得無今佛念諸佛耶？何故威神光光乃爾？』」"},{"p":"01-大正藏/09經集部類/T0627《文殊支利普超三昧經》.md","l":24,"id":"T0627","t":"文殊支利普超三昧經","x":"如斯正士、諸天子等，亦悉會坐各各講論，如是之儔迭相謂曰：「仁者欲知佛之智慧弘普無限，不可思議不可稱量，無能滅度盡極際者，不可以小意思原大德鎧，當以何方便誓被戒德鎧，而能逮茲大乘佛乘、諸通慧乘、不可思乘，斯應道乎？」"},{"p":"01-大正藏/01阿含部類/T0038《輪王七寶經》.md","l":32,"id":"T0038","t":"輪王七寶經","x":"「復次、諸苾芻！輪王出時復有女寶出現，最上色相諸分圓滿妙好第一，諸世間人無有等者，輕妙柔軟如幹唧梨，身諸毛孔出諸妙香。譬如盛香寶器，於一切時香氣常在。又復女寶所有出入之息，一一皆如青蓮華香，人所愛樂。如王所行女寶從後，諸有所作適悅自在，性行貞正不受邪染，常出愛語人所樂聞，面有光明人所喜見。諸苾芻！此名輪王出時第七女寶出現。」"},{"p":"01-大正藏/03般若部類/T1695《大般若波羅蜜多經般若理趣分述讚》.md","l":45,"id":"T1695","t":"大般若波羅蜜多經般若理趣分述讚","x":"問：處中有淨穢，不定但說一，諸方時不同，何妨亦定說。凡夫見穢處，知聖居淨土。何不別論此時說，準餘知別時。答：或一剎那或復多劫不可定說，準不解故，由是總相但言一時。其延促劫量，或唯識以促延、或所執以雙泯、或依他以妄法、或實性以平等、或聖力以加持，故有延促。無勞疑惑，義準應釋。"},{"p":"01-大正藏/10密教部類/T1082《觀世音菩薩祕密藏如意輪陀羅尼神呪經》.md","l":55,"id":"T1082","t":"觀世音菩薩祕密藏如意輪陀羅尼神呪經","x":"時觀世音菩薩憐愍眾生故，說：「眼藥法，令一切人見皆生愛樂歡喜。慢室迦拘竪、紅蓮花、青蓮花、海水末或烏賊魚末、牛黃、欝金香、漢欝金、畢撥、胡椒、乾薑。"},{"p":"01-大正藏/01阿含部類/T0029《鹹水喻經》.md","l":20,"id":"T0029","t":"鹹水喻經","x":"「彼云何人沒溺於水？或有一人以不善法盡纏裹身，純罪熟，至地獄一劫受罪不可療治，是謂此人常沒溺於水，是謂初入水沒溺。"},{"p":"01-大正藏/02本緣部類/T0152《六度集經》.md","l":20,"id":"T0152","t":"六度集經","x":"「布施度無極者，厥則云何？慈育人物，悲愍群邪，喜賢成度，護濟眾生，跨天踰地潤弘河海。布施眾生，飢者食之，渴者飲之，寒衣熱涼，疾濟以藥，車馬舟輿、眾寶名珍、妻子國土，索即惠之。猶太子須大拏，布施貧乏，若親育子，父王屏逐，愍而不怨。」"},{"p":"01-大正藏/04法華部類/T1919《天台智者大師禪門口訣》.md","l":12,"id":"T1919","t":"天台智者大師禪門口訣","x":"師言：安般守意，當知色、心相因而息，猶然火緣薪以煙。覩煙清、濁，則覽燥、濕之形；察息耎、麁，用鏡真、邪之候。守之者，庶使望雲造浦、候岸制篙，識其機道，船獲濟矣！"},{"p":"01-大正藏/09經集部類/T0618《達摩多羅禪經》.md","l":16,"id":"T0618","t":"達摩多羅禪經","x":"若乃將入其門，機在攝會，理玄數廣，道隱於文。則是阿難曲承音詔，遇非其人，必藏之靈府。何者？心無常規，其變多方；數無定像，待感而應。是故化行天竺，緘之有匠；幽關莫闢，罕闚其庭。從此而觀，理有行藏，道不虛授，良有以矣。"},{"p":"01-大正藏/10密教部類/T1066《大悲心陀羅尼修行念誦略儀》.md","l":18,"id":"T1066","t":"大悲心陀羅尼修行念誦略儀","x":"由此真言加持故，身口意業悉得清淨。然後五輪著地，歸命禮十方一切諸佛、諸大菩薩、方廣大乘，右膝著地，懺悔、隨喜、勸請、發願。"},{"p":"01-大正藏/04法華部類/T0277《佛說觀普賢菩薩行法經》.md","l":20,"id":"T0277","t":"佛說觀普賢菩薩行法經","x":"時三大士異口同音而白佛言：「世尊！如來滅後，云何眾生起菩薩心、修行大乘方等經典、正念思惟一實境界？云何不失無上菩提之心？云何復當不斷煩惱、不離五欲、得淨諸根、滅除諸罪？父母所生清淨常眼，不斷五欲而能得見諸障外事？」"},{"p":"01-大正藏/09經集部類/T0732《佛說罵意經》.md","l":16,"id":"T0732","t":"佛說罵意經","x":"人從色飲食得身，作人無所畏，但恐得畜生，從入地獄、餓鬼中耳！道人除鬚髮，行乞食，忍於飢渴；去家，棄財產；目不妄視，守護六根；避惡因緣，為欲脫苦。又起一意有百劫殃，譬如種穀百倍萬倍，穀無所知，常得萬倍。人意有知，恐不啻耳！"},{"p":"01-大正藏/09經集部類/T0557《佛說龍施女經》.md","l":24,"id":"T0557","t":"佛說龍施女經","x":"魔便下，化作女父形象，被服，謂龍施言：「今所念者大重。佛道難得，億百千劫勤勞不懈然後乃成。今世幸有佛，不如求羅漢，既要易得，且俱度世，泥洹無異。何為貪佛，久負勤苦？汝是我女，故語汝耳。」"},{"p":"01-大正藏/16淨土宗部類/T0368《拔一切業障根本得生淨土神呪》.md","l":20,"id":"T0368","t":"拔一切業障根本得生淨土神呪","x":"昔長安僧叡法師、慧崇、僧顯、慧通，近至後周實禪師、景禪師、西河鸞法師等數百餘人，並生西方。西河綽禪師等，因見鸞法師得生淨土，各率有緣，專修淨土之業；綽師又撰西方記驗，名《安樂集》流行。"},{"p":"01-大正藏/03般若部類/T0243《大樂金剛不空真實三麼耶經》.md","l":20,"id":"T0243","t":"大樂金剛不空真實三麼耶經","x":"時薄伽梵，一切如來大乘現證三麼耶一切曼荼羅持金剛勝薩埵，於三界中調伏無餘，一切義成就，金剛手菩薩摩訶薩，為欲顯明此義故，熈怡微笑，左手作金剛慢印，右手搊擲本初大金剛，作勇進勢，說大樂金剛不空三麼耶心："},{"p":"01-大正藏/07涅槃部類/T0394《佛入涅槃密迹金剛力士哀戀經》.md","l":18,"id":"T0394","t":"佛入涅槃密迹金剛力士哀戀經","x":"復作是言：「唯願真濟請為我起，我今薄祐無依憑處。云何世尊捨棄於我獨入寂滅？自今已後永離哀顏，世尊寂靜，身、口、意業更不可覩，更不得見佛婆伽婆入于佛住。"},{"p":"01-大正藏/04法華部類/T1918《四念處》.md","l":44,"id":"T1918","t":"四念處","x":"私記者雜錄：聲聞念處苦諦為首，緣覺集諦為首，菩薩道諦為首，通菩薩滅諦為首，別菩薩界外道諦為首，圓菩薩界外滅諦為首。又聲聞總相觀，緣覺別相觀，菩薩總別雙觀，通、別界內外次第觀，圓界內外圓觀。又聲聞因成假觀為首，緣覺相續假為首，菩薩相待假為首。"},{"p":"01-大正藏/08大集部類/T0403《阿差末菩薩經》.md","l":18,"id":"T0403","t":"阿差末菩薩經","x":"與大比丘眾六百萬人俱——心行和安，消滅塵勞、恩愛、眾弊，則是如來為法王子，修深奧法因正法生，威儀禮節進止光光，為大眾祐親歸如來。"},{"p":"01-大正藏/04法華部類/T1914《止觀大意》.md","l":22,"id":"T1914","t":"止觀大意","x":"故一家觀法入道次第稍異諸說，以附諸經成行相故，則內順觀道、外扶教門，依而修行必不空過。縱此生未獲，為種亦疆，意氣博達該括包籠，盡未來際不復改輒。若依之修行，咸須口訣方成一家行相。(湛然)所見暗短、稟承無功，本文三百餘紙，略此多有不周，雖俛仰以赴嚴命，實恐失大師深旨，諸有不逮，敢望通恕云耳。"},{"p":"01-大正藏/08大集部類/T0401《佛說無言童子經》.md","l":26,"id":"T0401","t":"佛說無言童子經","x":"無言菩薩承佛威神，大願所致，踊在空中去地四丈九尺，大菩薩眾亦復如是。無言大士而於中與菩薩異口同音，以偈讚佛："},{"p":"01-大正藏/04法華部類/T0267《不退轉法輪經》.md","l":28,"id":"T0267","t":"不退轉法輪經","x":"彼佛國中有二菩薩，一名善音，二名善聲，是二菩薩摩訶薩，皆已住阿鞞跋致地，決定當得阿耨多羅三藐三菩提，俱從蓮華臺中而出，更整衣服，右膝著地，一心合掌各白佛言：「世尊！娑婆世界去此幾何？」"},{"p":"01-大正藏/03般若部類/T0247《佛說了義般若波羅蜜多經》.md","l":16,"id":"T0247","t":"佛說了義般若波羅蜜多經","x":"是時尊者舍利子，合掌恭敬前白佛言：「世尊！如世尊言，諸有菩薩摩訶薩樂欲修習般若波羅蜜多相應行者，云何了知諸法自性？於諸所作云何離相？」"},{"p":"01-大正藏/06寶積部類/T0333《佛說大乘日子王所問經》.md","l":18,"id":"T0333","t":"佛說大乘日子王所問經","x":"是時無比摩建儞迦女而起瞋恚，憎嫉舍摩嚩底妃后，於日子王邊說言：「天子知耶？舍摩嚩底妃后等五百女，共其沙門而行婬慾。我今告言，要天子知，實難容恕。」"},{"p":"01-大正藏/09經集部類/T0620《治禪病祕要法》.md","l":24,"id":"T0620","t":"治禪病祕要法","x":"釋子比丘——禪難提、優波難提等——心驚毛竪，於風大觀發狂癡想，從禪定起，如醉象奔不可禁制。"},{"p":"01-大正藏/16淨土宗部類/T0364《佛說大阿彌陀經》.md","l":41,"id":"T0364","t":"佛說大阿彌陀經","x":"如為薦亡、或禳災、或保安，則隨意祝願，不須如前祈禱。亦須誦真言，先歸依三寶及西方四聖，然後祝願。若為自身往生，則宜一一如前，其功德甚大矣。"},{"p":"01-大正藏/10密教部類/T0859《供養儀式》.md","l":51,"id":"T0859","t":"供養儀式","x":"此真言印，或餘經說，如是通用不違背，若能解了旋轉者，諸有所作皆成就。次若揣土時，亦須密印真言，真言曰："},{"p":"01-大正藏/07涅槃部類/T0374《大般涅槃經》.md","l":14,"id":"T0374","t":"大般涅槃經","x":"大般涅槃經者，蓋是法身之玄堂，正覺之實稱，眾經之淵鏡，萬流之宗極。其為體也，妙存有物之表、周流無窮之內，任運而動、見機而赴，任運而動，則乘虛照以御物，寄言蹄以通化；見機而赴，則應萬形而為像，即群情而設教。至乃形充十方而心不易慮，教彌天下而情不在已；廁流塵蟻而弗下，彌蓋群聖而不高；功濟萬化而不恃，明踰萬日而不居；渾然與太虛同量，泯然與法性為一。"},{"p":"01-大正藏/03般若部類/T0248《佛說五十頌聖般若波羅蜜經》.md","l":20,"id":"T0248","t":"佛說五十頌聖般若波羅蜜經","x":"「須菩提！此般若波羅蜜經具足方便，通達一切諸佛菩薩甚深法藏，應如是學、如是修行。"},{"p":"01-大正藏/04法華部類/T1915《修習止觀坐禪法要》.md","l":32,"id":"T1915","t":"修習止觀坐禪法要","x":"一者、若人未作佛弟子時，不造五逆；後遇良師，教受三歸五戒，為佛弟子。若得出家，受沙彌十戒，次受具足戒，作比丘、比丘尼。從受戒來，清淨護持，無所毀犯；是名上品持戒人也。當知是人修行止觀，必證佛法；猶如淨衣，易受染色。"},{"p":"01-大正藏/09經集部類/T0656《菩薩瓔珞經》.md","l":24,"id":"T0656","t":"菩薩瓔珞經","x":"時有菩薩名曰普照，承佛聖旨，即從座起長跪叉手，前白佛言：「今所神感未曾見聞，此何瑞應乃至於斯？唯願大聖敷演其義，使諸會者永無狐疑。」"},{"p":"01-大正藏/09經集部類/T0743《佛說忠心經》.md","l":24,"id":"T0743","t":"佛說忠心經","x":"梵志驚曰：「此山已起，誰迴之乎？日又無光，此將有以！」中有明者，以定意觀眾弟子心，誰穢濁者，令山不移？覩見諸心，普有道淨，國榮寶色，不穢其心。仰頭觀見，覩一沙門，當其山上。梵志僉曰：「正是瞿曇弟子所為。」梵志呼曰：「王令吾等為民除患，汝抑之為？」"},{"p":"01-大正藏/17禪宗部類/T1989《潭州溈山靈祐禪師語錄》.md","l":20,"id":"T1989","t":"潭州溈山靈祐禪師語錄","x":"雲巖到溈山。師問。承聞長老在藥山弄師子。是否。雲巖云。是。師云。長弄有置時。雲巖云。要弄即弄。要置即置。師云。置時。師子在甚麼處。雲巖云。置也。置也(法昌遇云。好一場師子。只是有頭無尾。我當時若見溈山道置時師子在甚麼處。便與放出踞地金毛。直教溈山藏身無路)。"},{"p":"01-大正藏/02本緣部類/T0185《太子瑞應本起經》.md","l":16,"id":"T0185","t":"太子瑞應本起經","x":"「吾自念宿命，無數劫時，本為凡夫。初求佛道已來，精神受形，周遍五道。一身死壞，復受一身，生死無量。譬喻盡天下草木，斬以為籌，計吾故身，不能數矣。"},{"p":"01-大正藏/04法華部類/T1926《法華經安樂行義》.md","l":14,"id":"T1926","t":"法華經安樂行義","x":"《法華經》者，大乘頓覺，無師自悟，疾成佛道，一切世間難信法門。凡是一切新學菩薩欲求大乘，超過一切諸菩薩，疾成佛道，須持戒、忍辱、精進，勤修禪定，專心勤學法華三昧。"},{"p":"01-大正藏/09經集部類/T0765《本事經》.md","l":25,"id":"T0765","t":"本事經","x":"吾從世尊聞如是語：「苾芻當知！我觀世間，無別一法，繫縛群生，馳騁流轉生死長途，如貪愛結。所以者何？世間群生，由貪愛結所繫縛故，馳騁流轉生死長途。是故汝等應如是學：我當云何修瑩慧刀，斷貪愛結，破大闇聚？汝等苾芻，應如是學。」爾時，世尊重攝此義而說頌曰："},{"p":"01-大正藏/18史傳部類/T2027《迦葉結經》.md","l":14,"id":"T2027","t":"迦葉結經","x":"聞如是一時世尊滅度未久。諸羅漢等悉會共議。未集經藏法律諸議。各心念言。吾等所作已辦。越塵勞山枯竭愛河。一切智日佛。天中天眼忽不見。吾等患厭載攝是身。今欲般泥洹即說偈曰。"},{"p":"01-大正藏/03般若部類/T0224《道行般若經》.md","l":22,"id":"T0224","t":"道行般若經","x":"佛在羅閱祇耆闍崛山中，摩訶比丘僧不可計，諸弟子舍利弗、須菩提等；摩訶薩菩薩無央數，彌勒菩薩、文殊師利菩薩等。"},{"p":"01-大正藏/06寶積部類/T0316《佛說大乘菩薩藏正法經》.md","l":147,"id":"T0316","t":"佛說大乘菩薩藏正法經","x":"「復次長者！邪定聚法世間合集，斯苦甚大。邪法有十。何等為十？一者邪見，二者邪思惟，三者邪語，四者邪業，五者邪命，六者邪勤，七者邪念，八者邪定，九者邪解脫，十者邪智。如是十種邪定聚法世間合集，斯苦甚大，我見是已，普令超越一切邪法，是故我乃淨信出家，趣證阿耨多羅三藐三菩提果。」"},{"p":"01-大正藏/05華嚴部類/T0283《菩薩十住行道品》.md","l":42,"id":"T0283","t":"菩薩十住行道品","x":"「波藍耆兜波菩薩教有十事。何等為十事？一者、當供養佛諸菩薩，二者、隨其所樂當教語，三者、所生處皆尊貴，四者、天上天下一無有能及者，五者、佛所有智悉當逮得，六者、波羅世所生處常見無央數佛，七者、所有深三昧經悉當逮得，八者、死生道無邊幅處以來，九者、命既去不久，十者、若悉當度脫十方人。所以者何？益入於佛法中故。"},{"p":"01-大正藏/01阿含部類/T0065《伏婬經》.md","l":18,"id":"T0065","t":"伏婬經","x":"「汝居士！世間有十伏婬。云何為十？此居士，或一伏婬，非法行婬干彼，非法求婬干(無所方便為苦)已，亦不自安身，亦不安父母及妻子、客使奴婢、沙門婆羅門，不有益事，為善得善得生天上。如是，居士！是一伏婬。"},{"p":"01-大正藏/06寶積部類/T0329《佛說須賴經》.md","l":26,"id":"T0329","t":"佛說須賴經","x":"須賴答言：「莫說是語。所以者何？不善讒人者殺生之報，正使彼等刀割我身，破如跋跙樹，尊尚不發惡意加於彼等。所以者何？一切諸法報應有二：種善者生善道、種惡者墮惡道。以是故，我不敢恨彼，況欲斷彼命？」"},{"p":"01-大正藏/16淨土宗部類/T1966《念佛鏡》.md","l":14,"id":"T1966","t":"念佛鏡","x":"愛不重，不生娑婆；念不一，不生極樂。娑婆穢土也，極樂淨土也；娑婆之壽則有量，彼土之壽則無量矣；娑婆備諸苦，彼土則安養無苦矣；娑婆隨業轉輪生死，彼土一往則永證無生法忍，若願度生，則任意自在，不為諸業轉矣。其淨穢、壽量、苦樂、生死如是差別，而眾生冥然不知，可不哀哉！"},{"p":"01-大正藏/04法華部類/T0270《大法鼓經》.md","l":22,"id":"T0270","t":"大法鼓經","x":"復有差摩比丘尼與比丘尼眾俱、毘舍佉鹿子母、及末利夫人，各與無量大眷屬俱；須達長者、與諸優婆塞俱。"},{"p":"01-大正藏/05華嚴部類/T1740《大方廣佛華嚴經中卷卷大意略敘》.md","l":56,"id":"T1740","t":"大方廣佛華嚴經中卷卷大意略敘","x":"毘盧舍那，往劫曾為太子威光，供十須彌山微塵數諸如來，令獲十蓮華藏世界之果海。"},{"p":"01-大正藏/04法華部類/T1923《諸法無諍三昧法門》.md","l":18,"id":"T1923","t":"諸法無諍三昧法門","x":"問曰：《般若經》中佛自說言：「欲學聲聞，當學般若。欲學緣覺，當學般若。欲學菩薩，當學般若。復次，有六波羅蜜，般若為前導，亦是三世諸佛母。」汝今云何偏讚禪，不讚五波羅蜜？復次，如經中說：「五度如盲，般若如眼。」汝今云何偏讚度，不讚明眼？誰能信者？願廣解說，除我等疑惑。答曰：諦聽，善思念之，吾當為汝決定說。"},{"p":"01-大正藏/18史傳部類/T2054《唐大薦福寺故寺主翻經大德法藏和尚傳》.md","l":35,"id":"T2054","t":"唐大薦福寺故寺主翻經大德法藏和尚傳","x":"第三科曰。及總章元年儼將化去藏猶居俗(時年二十六)。儼乃累道成薄塵二大德曰。此賢者注意於華嚴。蓋無師自悟。紹隆遺法其惟是人。幸假餘光俾沾制度。至咸亨元年(藏年二十八)榮國夫人奄歸冥路。則天皇后廣樹福田度人。則擇上達僧捨宅乃成太原寺。於是受顧託者連狀薦推。帝諾曰俞仍𮨕新剎。周羅遂落敻𭠮常科。此之謂削染因緣。豈非以方便心推求簡擇趣真方便乎。"},{"p":"01-大正藏/03般若部類/T0231《勝天王般若波羅蜜經》.md","l":24,"id":"T0231","t":"勝天王般若波羅蜜經","x":"時普光如來告離障菩薩摩訶薩言：「善男子！西方去此過十恒河沙世界，有佛國土名曰娑婆，佛號釋迦牟尼如來、應供、正遍知、明行足、善逝、世間解、無上士、調御丈夫、天人師、佛、世尊，今欲為諸菩薩說摩訶般若波羅蜜，以是因緣放此光明。」"},{"p":"01-大正藏/16淨土宗部類/T0365《佛說觀無量壽佛經》.md","l":55,"id":"T0365","t":"佛說觀無量壽佛經","x":"時韋提希被幽閉已，愁憂憔悴；遙向耆闍崛山，為佛作禮，而作是言：「如來世尊在昔之時，恒遣阿難來慰問我；我今愁憂，世尊威重，無由得見；願遣目連、尊者阿難，與我相見。」作是語已，悲泣雨淚，遙向佛禮。未舉頭頃，爾時世尊在耆闍崛山，知韋提希心之所念，即勅大目揵連及以阿難，從空而來。佛從耆闍崛山沒，於王宮出。"},{"p":"01-大正藏/05華嚴部類/T0280《佛說兜沙經》.md","l":22,"id":"T0280","t":"佛說兜沙經","x":"不可計佛處、不可計法處、不可計諸大十方人民處、不可計佛剎處，過去、當來、今現在佛等所出生也。"},{"p":"01-大正藏/09經集部類/T0615《菩薩訶色欲法經》.md","l":14,"id":"T0615","t":"菩薩訶色欲法經","x":"女色者，世間之枷鎖，凡夫戀著，不能自拔。女色者，世間之重患，凡夫困之，至死不免。女色者，世間之衰禍，凡夫遭之，無厄不至。行者既得捨之，若復顧念，是為從獄得出，還復思入；從狂得正，而復樂之；從病得差，復思得病。智者怒之，知其狂而顛蹶，死無日矣！"},{"p":"01-大正藏/18史傳部類/T2044《天尊說阿育王譬喻經》.md","l":26,"id":"T2044","t":"天尊說阿育王譬喻經","x":"昔天尊在恒水邊。廣說經法。時天龍鬼神帝王人民飛鳥走獸皆來聽法。時有放牛老公柱杖而聽。不覺杖下有蝦蟆。蝦蟆聽經意美。亦不覺背上有杖。遂久蝦蟆命終。其神即生天上。用天眼觀其本。從何道中來乃見故身在蝦蟆中。來天華散其故身上。示語後世人。蝦蟆中聽經意美得生天上。況於賢者至心聽經。豈不巍巍乎。"},{"p":"01-大正藏/06寶積部類/T0344《佛說太子和休經》.md","l":16,"id":"T0344","t":"佛說太子和休經","x":"阿闍世王太子，名為和休，與長者子五百人，各持金花繖蓋，從羅閱國出行，與太子相隨俱到佛所，各持繖蓋上佛已，各叉手頭面著地為佛作禮，却住佛前。太子叉手白佛言：「菩薩何因緣得端正？何因緣不入女人腹中，而生蓮花中？何因緣知前世宿命？願佛加大恩，當為我分別說之。」"},{"p":"01-大正藏/03般若部類/T0234《佛說濡首菩薩無上清淨分衛經》.md","l":20,"id":"T0234","t":"佛說濡首菩薩無上清淨分衛經","x":"其諸菩薩悉皆各有，名曰濡首童真菩薩、龍首菩薩、妙首菩薩、大首菩薩、普首菩薩、慧首菩薩、明首菩薩、甘首菩薩、英首菩薩、寶首菩薩，是等菩薩，千人俱也。"},{"p":"01-大正藏/08大集部類/T0418《般舟三昧經》.md","l":20,"id":"T0418","t":"般舟三昧經","x":"時佛放威神，諸比丘所在遠方無不來者。即時十萬比丘俱相隨來會佛所，前為佛作禮，却坐一面。"},{"p":"01-大正藏/09經集部類/T0455《佛說彌勒下生成佛經》.md","l":231,"id":"T0455","t":"佛說彌勒下生成佛經","x":"按《開元錄》，《彌勒下生經》前後六譯，三存三失，而此本亦在三存之一也，則宋藏無此經者，失之耳，今得於丹藏而編入之。"},{"p":"01-大正藏/10密教部類/T1029《佛說安宅陀羅尼呪經》.md","l":18,"id":"T1029","t":"佛說安宅陀羅尼呪經","x":"「多跌他　波羅殊隷　殊隷　殊隷隷沙摩鞮摩訶娑摩鞮　娑慢帝　摩訶娑慢帝　娑隷娑羅隷　莎呵」"},{"p":"01-大正藏/01阿含部類/T0075《佛為黃竹園老婆羅門說學經》.md","l":22,"id":"T0075","t":"佛為黃竹園老婆羅門說學經","x":"「此婆羅門！有方便我可有慢，不如汝所說。此婆羅門！有色之味、聲之味、香之味、細滑之味，是如來已盡、已知，斷除根本，當來恐怖不復生法。此婆羅門！有是方便，令我有慢，不如汝所說。」"},{"p":"01-大正藏/09經集部類/T0778《佛說菩薩內習六波羅蜜經》.md","l":20,"id":"T0778","t":"佛說菩薩內習六波羅蜜經","x":"佛言：「三、止，為羼提波羅蜜。意欲、婬怒、瞋恚能忍不為；口欲、甘肥、美味、身欲得細滑，自制意能忍、不受，是為內羼提波羅蜜，為忍辱得度。」"},{"p":"01-大正藏/05華嚴部類/T0294《佛說羅摩伽經》.md","l":56,"id":"T0294","t":"佛說羅摩伽經","x":"「善男子！汝今當知，我常不起眾生相，不著眾生相，眾生無相故；知一切語言音聲，而不著音聲，音聲無性相故。見一切佛光明相好，而不著相好。何以故？深知法身無色相故。受持一切諸佛法輪，而亦不著法輪之相，深心解了諸法真如實際法性相故。於念念中，充滿普遍虛空法界，而亦不著法界相，善能了知一切諸法如幻化相故。善男子！我唯知此一切種智，普能開現無底菩薩法門。"},{"p":"01-大正藏/17禪宗部類/T2009《少室六門》.md","l":211,"id":"T2009","t":"少室六門","x":"問。六趣三界廣大無邊。若唯觀心。何由免無窮之苦。答。三界業報唯心所生。本若無心。於三界中。即出三界。其三界者。即三毒也。貪為欲界。嗔為色界。癡為無色界。故名三界。由此三毒。造業輕重。受報不同。分歸六處。故名六趣。"},{"p":"01-大正藏/09經集部類/T0708《了本生死經》.md","l":16,"id":"T0708","t":"了本生死經","x":"於是賢者舍利弗謂諸比丘言：「諸賢者！佛說：『若諸比丘見緣起為見法，已見法為見我。』此謂何義？是說有緣。若見緣起無命、非命，為見法；見法無命、非命，為見佛。當隨是慧。"},{"p":"01-大正藏/07涅槃部類/T0387《大方等無想經》.md","l":20,"id":"T0387","t":"大方等無想經","x":"復有比丘尼眾六萬五千，摩訶波闍波提比丘尼而為上首，亦於晨朝從禪定起，往至佛所，頭面禮足，合掌恭敬、右遶三匝，修敬已畢，却坐一面。"},{"p":"01-大正藏/01阿含部類/T0035《海八德經》.md","l":18,"id":"T0035","t":"海八德經","x":"尊德目連，一心入定，道眼淨觀，具見彼心有可棄之行矣。目連即與謂之曰：「起！非爾俗夫所應坐處也。」彼不肯起，牽臂使出曰：「爾無至德，心懷六邪，何敢以臭溷之體，坐天香之座？爾是棄人，非沙門矣。」目連即還就清淨座。"},{"p":"01-大正藏/03般若部類/T0238《金剛能斷般若波羅蜜經》.md","l":24,"id":"T0238","t":"金剛能斷般若波羅蜜經","x":"世尊於此言：「此，善實！菩薩乘發行，如是心發生應：『所有，善實！眾生，眾生攝攝已，卵生、若胎生、若濕生、若化生，若色、若無色，若想、若無想、若非想非無想，所有眾生界施設已，彼我一切無受餘涅槃界滅度應。』如是無量雖眾生滅度，無有一眾生滅度有。彼何所因？若，善實！菩薩摩訶薩眾生想轉，不彼菩薩摩訶薩名說應。彼何所因？不彼，善實！菩薩名說應，若眾生想轉，壽想若、人想若轉。"},{"p":"01-大正藏/09經集部類/T0535《佛說申日經》.md","l":32,"id":"T0535","t":"佛說申日經","x":"明日時至，來詣請所，諸尼犍子無有法則，亂行併肩先入無上，適至門中皆各使走，却墮泥坑污其衣服，皆悉瞋恚各欲還去。"},{"p":"01-大正藏/09經集部類/T0444《佛說百佛名經》.md","l":18,"id":"T0444","t":"佛說百佛名經","x":"時，尊者舍利弗即從坐起，整理衣服，右膝著地，合十指掌，而白佛言：「唯願世尊，演說十方現在世界諸佛名號。所以者何？若有善男子、善女人，聞是現在諸佛名者，生大功德，發阿耨多羅三藐三菩提心，得不退轉，亦當速成阿耨多羅三藐三菩提。」"},{"p":"01-大正藏/04法華部類/T1724《法華玄贊義決》.md","l":18,"id":"T1724","t":"法華玄贊義決","x":"問：既定生時，即無多生又不造業，如何不定？誰言不造業？論說有支非攝二位，以憎背有故，若許造業，何非有支？"},{"p":"01-大正藏/09經集部類/T0496《佛說大迦葉本經》.md","l":22,"id":"T0496","t":"佛說大迦葉本經","x":"時畢撥學志即從坐起，往詣叢樹，遙見世尊光明百千，足底相文，眾好具足，即時歎曰：「吾等先古神仙所遺經典，說有瑞應三十二大人之相分別具足，當趣二處：設在家者為轉輪聖王，主四天下，選擇要教，治以正法，刀杖兵甲，制而不施；假使出家，棄國捐王，當為如來、至真、等正覺、明行成為、善逝、世間解、無上士、道法御、天人師，號佛世尊。寧可親覲。」"},{"p":"01-大正藏/09經集部類/T0612《身觀經》.md","l":22,"id":"T0612","t":"身觀經","x":"「以勤苦治生致財物，自愛身命綺好，人死時皆棄所有，身僵在地，下入於土，但為陰去，生隨行受形人；譬如樹果實已見，如是為有人意墮有中，天下一切果物，一人得不自足，若得一分，當那得自厭無有數？三十五樂自樂遍之，當為有何等益？"},{"p":"01-大正藏/03般若部類/T0232《文殊師利所說摩訶般若波羅蜜經》.md","l":20,"id":"T0232","t":"文殊師利所說摩訶般若波羅蜜經","x":"佛知眾會皆悉集已，爾時如來從住處出，敷座而坐。告舍利弗：「汝今何故，於晨朝時在門外立？」舍利弗白佛言：「世尊！文殊師利童真菩薩先已至此，住門外立。我實於後晚來到耳。」"},{"p":"01-大正藏/05華嚴部類/T0291《佛說如來興顯經》.md","l":20,"id":"T0291","t":"佛說如來興顯經","x":"其名曰：普賢菩薩、普稱尊菩薩、如來族姓成首菩薩、金剛幢英菩薩、無蓋月淨菩薩、日光離垢藏菩薩、大神通變動菩薩、離垢光首、十方精進王、大師子娛樂神通菩薩。如是等類，猶如十方不可計數億百千姟諸佛之土滿中眾塵，眾會菩薩，其數如斯。"},{"p":"01-大正藏/05華嚴部類/T1733《華嚴經探玄記》.md","l":31,"id":"T1733","t":"華嚴經探玄記","x":"次別顯者，略提十義以明無盡。何者為十？謂由法爾故、願力故、機感故、為本故、顯德故、顯位故、開發故、見聞故、成行故、得果故。"},{"p":"01-大正藏/01阿含部類/T0014《人本欲生經》.md","l":58,"id":"T0014","t":"人本欲生經","x":"「如是，阿難！為從是有、從是本、從是習、從是因緣，貪欲為有，發往因緣令有欲貪，從是利故，阿難！令發往。為從是說是。當從是因緣知，為從利因緣令發往。若，阿難！以無有利亦無有求，亦何因緣有求？一切，阿難！已無有利，寧當有發往不？」"},{"p":"01-大正藏/06寶積部類/T0354《毘耶娑問經》.md","l":12,"id":"T0354","t":"毘耶娑問經","x":"菩薩方便攝化眾生，必以大悲引邪從正。毘耶娑仙，即其人也。為導群迷令識因果，將諸異見至如來所，歸命諮啟，聽聞正法。因其請說，即以名經，故因此部「毘耶娑問」。"},{"p":"01-大正藏/09經集部類/T0533《菩薩生地經》.md","l":20,"id":"T0533","t":"菩薩生地經","x":"佛言：「大哉！差摩竭！乃問菩薩之行，忍辱為本，以立忍力乃疾得佛。忍有四事，何等為四？一曰、若罵詈者，默而不報；二曰、若撾捶者，受而不挍；三曰、若瞋恚者，慈心向之；四曰、若輕毀者，不念其惡。」"},{"p":"01-大正藏/16淨土宗部類/T1970《龍舒增廣淨土文》.md","l":14,"id":"T1970","t":"龍舒增廣淨土文","x":"延祐三年歲次丙辰中秋日，同修淨土信士、奉訓大夫前江淮守處財賦都總府副總官古壽呂師說，書于潯陽寓舍之信堂。"},{"p":"01-大正藏/07涅槃部類/T0381《等集眾德三昧經》.md","l":24,"id":"T0381","t":"等集眾德三昧經","x":"佛言：「有三昧名等集眾德，假使菩薩逮斯定者，眾德進益，不乏智慧、不違禪定，所慕道心未曾闕廢，心性弘毅未曾離佛，恒聞經法，供養聖眾行于四恩，彼如是已不捨群生。」於時世尊，諮嗟等集眾德三昧，宣揚其名默然無言。"},{"p":"01-大正藏/09經集部類/T0713《貝多樹下思惟十二因緣經》.md","l":22,"id":"T0713","t":"貝多樹下思惟十二因緣經","x":"「比丘！便思惟念：『何以故為生？亦何因緣復生？』比丘！便自思惟案本念，便得是應意：『為有故生，亦因緣有復生。』"},{"p":"01-大正藏/10密教部類/T1052《讚觀世音菩薩頌》.md","l":90,"id":"T1052","t":"讚觀世音菩薩頌","x":"以此讚歎觀世音菩薩功德，上資國主聖神皇帝陛下善轉金輪，色力壽命永無窮盡，智慧果報不可思議，恒御閻浮長居震旦，擁護三寶利益群生，一切含靈皆蒙聖福。"}];

  global.PassagesData = {
    list: list,
    count: list.length,

    /*
     * 一律讀 this.list，不讀閉包裡的 list。
     *
     * 兩者原本是同一份參考，但外部一旦替換 PassagesData.list（測試會
     * 這麼做），閉包還握著舊資料——這種「改了沒生效」的分岔很難查。
     */
    after: function (idx, n) {
      var arr = this.list || [];
      var out = [];
      if (!arr.length) return out;
      for (var i = 1; i <= (n || 1); i++) {
        out.push(arr[(((idx + i) % arr.length) + arr.length) % arr.length]);
      }
      return out;
    },

    at: function (idx) {
      var arr = this.list || [];
      if (!arr.length) return null;
      return arr[((idx % arr.length) + arr.length) % arr.length];
    }
  };
})(typeof window !== 'undefined' ? window : this);
